    '.ai365-res-cardw > .ai365-res-card{flex:1;padding:0;border:0;border-radius:0;background:none;}',
    '.ai365-res-card{display:flex;align-items:center;gap:12px;border:1px solid var(--soft-2);border-radius:12px;padding:8px 12px;background:var(--soft-2);text-align:left;min-width:0;}',
    '.ai365-res-card .ic{width:22px;height:22px;border-radius:6px;display:flex;align-items:center;justify-content:center;flex-shrink:0;}',
    '.ai365-res-card .tt{font-size:14px;line-height:20px;font-weight:600;color:var(--ink-2);display:block;}',
