    '.ai365-res-chip:hover{border-color:var(--primary);color:var(--primary);}',
    '.ai365-fn{font-size:10px;font-weight:700;color:var(--primary);background:var(--primary-soft);border-radius:4px;padding:0 4px;margin-left:2px;vertical-align:super;line-height:1.4;cursor:pointer;}',
    '.ai365-fn:hover{background:var(--soft-2,#E4EDFF);}',
    '.artifact-panel.open.ai365-res-narrow{width:420px;max-width:62%;}',
    /* 좁은 모드 가로 스크롤 제거 — 목업 기본 min-width:460px가 420px 패널보다 넓어 생기는 문제. 세로만 스크롤 */
