    '.ai365-src-num{font-size:10px;font-weight:700;color:var(--primary);background:var(--primary-soft);border-radius:50%;min-width:18px;height:18px;display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;margin-right:7px;}',
    /* 로컬 지식(2026-09-30): 배지 · 문서 칩 · 캡션 · 실행 프레임 로컬 카드 · 미리보기 텍스트 / local knowledge: badge, document chips, captions, the frame's local card, preview text */
    '.ai365-local-badge{display:inline-flex;align-items:center;margin:0;padding:0 7px;border-radius:999px;font-size:10px;font-weight:600;line-height:17px;color:#B45309;background:#FFF4E5;border:1px solid #F6D3A1;vertical-align:1px;white-space:nowrap;font-style:normal;}',
