/* ── 데이터·지식 미리보기 ── */
let AI365_FLP_PREV_CACHE = {};   // 테이블 → preview 응답 캐시(뷰애즈 전환 시 폐기)
let AI365_FLP_KPREV_CUR = null;  // 지식 PDF 뷰어의 현재 파일

function ai365FlpPrevSync(domain) {
  const el = document.getElementById('ai365FlpPrev');
  if (!el) return;
  const H = window.AI365_SMF_HOOKS;
  const scope = (H && H.scope) ? H.scope() : { data_tables: [], data_bi: [], knowledge_files: [] };
  if (domain === 'data') ai365FlpPrevData(el, scope);
  else if (domain === 'knowledge') ai365FlpPrevKnowledge(el, scope);
}

function ai365FlpBiLabel(f) {
  const ws = (window.AI365_WORKSPACES || []);
  for (let i = 0; i < ws.length; i++) {
    const hit = (ws[i].bi || []).find(function (it) { return it.file === f; });
    if (hit) return hit.name || f;
  }
  return f;
}

/* 테이블 라벨·종류·워크스페이스를 클라이언트에서 즉시 해석 — 접힌 카드가 원시 테이블명+DB 고정 배지로
   보이던 불일치 수정(서버 조회 없이 워크스페이스 슬롯의 name·버킷으로 판정, 캐시 응답과 동일 원천) */
/* Resolve a table's label/kind/workspace client-side — fixes collapsed cards showing raw table names
   with a hardcoded DB badge (slot name + bucket decide, same source the server uses) */
function ai365FlpTableMeta(t) {
  const ws = (window.AI365_WORKSPACES || []);
  for (let i = 0; i < ws.length; i++) {
    const w = ws[i];
    const s = (w.sql || []).find(function (it) { return it.table === t; });
    if (s) return { label: s.name || t, kind: 'DB', ws: w.name || '' };
    const c = (w.csv || []).find(function (it) { return it.table === t; });
    if (c) return { label: c.name || t, kind: 'CSV', ws: w.name || '' };
  }
  return { label: t, kind: 'DB', ws: '' };
}

/* 아코디언(2026-08-19 정돈 개편 — 사용자: "아래로 쭉 나열식이라 정돈이 안 됨"):
   카드는 기본 접힘(헤더만), 방금 체크로 새로 생긴 카드 1개만 자동 펼침. 열린 카드는 항상 1개(아코디언).
   테이블 조회는 **펼칠 때만** 수행(캐시) — 접힌 카드는 서버 호출이 없다. */
/* Accordion (tidy-up 2026-08-19 — user: the plain vertical stack felt untidy): cards render collapsed
   (header only); only the just-checked card auto-expands, and at most one card is open. Table fetches
   run only on expand (cached) — collapsed cards cost no server calls. */
let AI365_FLP_PREV_OPENKEY = null;
const AI365_FLP_PREV_CARET = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="6 9 12 15 18 9"/></svg>';

function ai365FlpPrevData(el, scope) {
  // 3차 프레임(2026-08-23 시안 2·5): 항목 목록(타입 배지) + 데이터 탐색기 / BI 임베드 카드 — 구현은 파일 말미 ai365DataPrevRender
  // Round-3 frame (designs 2·5): item list (type badges) + data explorer / BI embed card — implemented by ai365DataPrevRender (end of file)
  ai365DataPrevRender(el, scope);
}

let AI365_FLP_KPREV_FOLD = false;   // 지식 뷰어 접힘 상태 — 접어도 iframe은 DOM에 남아 재로드 없음
// knowledge viewer fold state — the iframe stays in the DOM while folded (no reload)

const AI365_KPT_FOLDER_IC = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7a2 2 0 0 1 2-2h4l2 2.5h8a2 2 0 0 1 2 2V17a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg>';
const AI365_KPT_FILE_IC = '<svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5"/></svg>';

function ai365FlpKnFindNode(id) {
  let hit = null;
  (function walk(nodes) {
    for (let i = 0; i < nodes.length; i++) {
      if (nodes[i].id === id) { hit = nodes[i]; return true; }
      if (nodes[i].children && nodes[i].children.length && walk(nodes[i].children)) return true;
    }
    return false;
  })(window.AI365_KNOWLEDGE || []);
  return hit;
}

/* 체크한 폴더를 뿌리로 한 폴더/파일 트리(사용자 요청 — 칩 나열 대신 트리 구조). 파일 클릭=뷰어 전환 */
/* A folder/file tree rooted at the checked folders (user request — tree instead of a chip list). File click switches the viewer */
function ai365FlpKnTreeHtml(node, depth) {
  const pad = 8 + depth * 14;
  let h = '<div class="ai365-kpt-folder" style="padding-left:' + pad + 'px">' + AI365_KPT_FOLDER_IC
    + '<span>' + ai365Esc(node.name) + '</span></div>';
  (node.files || []).forEach(function (f) {
    const on = f.name === AI365_FLP_KPREV_CUR;
    h += '<button type="button" class="ai365-kpt-file' + (on ? ' on' : '') + '" data-kprev="' + ai365Esc(f.name)
      + '" style="padding-left:' + (pad + 18) + 'px" title="' + ai365Esc(f.name) + '">' + AI365_KPT_FILE_IC
      + '<span>' + ai365Esc(f.name) + '</span></button>';
  });
  (node.children || []).forEach(function (c) { h += ai365FlpKnTreeHtml(c, depth + 1); });
  return h;
}

function ai365FlpPrevKnowledge(el, scope) {
  // 3차 프레임(2026-08-23, 시안 2·3): 체크로 풀린 파일의 **평면 목록** 카드 + 클릭한 파일만 아래 뷰어에
  // (자동 로드 없음). 접기는 표시만 토글(PDF 리로드 방지), 같은 파일 재클릭은 뷰어 닫기.
  // Round-3 frame (designs 2·3): a FLAT list card of the files resolved by checks + a viewer below for
  // the clicked file only (no auto-load). Fold is display-only (no PDF reload); re-click closes the viewer.
  const files = (scope.knowledge_files || []).slice();
  if (!files.length) { el.innerHTML = ''; el.removeAttribute('data-sig'); AI365_FLP_KPREV_CUR = null; AI365_FLP_KPREV_FOLD = false; return; }
  if (AI365_FLP_KPREV_CUR && files.indexOf(AI365_FLP_KPREV_CUR) < 0) AI365_FLP_KPREV_CUR = null;
  const sig = files.join('|') + '#' + (AI365_FLP_KPREV_CUR || '') + '::' + (AI365_FLP_KPREV_FOLD ? 1 : 0);
  if (el.getAttribute('data-sig') === sig) return;
  el.setAttribute('data-sig', sig);
  const rows = files.map(function (f) {
    const on = f === AI365_FLP_KPREV_CUR;
    return '<button type="button" class="ai365-kpl-file' + (on ? ' on' : '') + '" data-kprev="' + ai365Esc(f) + '" title="' + ai365Esc(f) + '">'
      + AI365_KPT_FILE_IC + '<span>' + ai365Esc(f) + '</span></button>';
  }).join('');
  el.innerHTML = '<div class="ai365-flprev-card ai365-kpl' + (AI365_FLP_KPREV_FOLD ? '' : ' open') + '">'
    + '<div class="ai365-flprev-hd" data-kpfold><b>' + ai365T('문서 미리보기') + '</b><span class="ai365-flprev-badge">' + files.length + '</span>'
    + '<span class="ai365-flprev-caret ai365-kpl-caret">' + AI365_FLP_PREV_CARET + '</span></div>'
    + '<div class="ai365-flprev-kbody"' + (AI365_FLP_KPREV_FOLD ? ' style="display:none"' : '') + '><div class="ai365-kpl-list">' + rows + '</div></div></div>'
    + (AI365_FLP_KPREV_CUR
      ? '<div class="ai365-flprev-card ai365-kpv"><iframe class="ai365-kprev-frame" src="/api/resources/knowledge/file/' + encodeURIComponent(AI365_FLP_KPREV_CUR) + '" title="' + ai365Esc(AI365_FLP_KPREV_CUR) + '"></iframe></div>'
      : '');
}

/* 리포트 에이전트 등 아티팩트 패널이 열리면 3분할 패널을 숨긴다(가로 공간 겹침으로 UI가 깨지는 것 방지
   — 사용자 요청). 닫히면 복원. 클래스 관찰이라 어떤 열림 경로든 커버된다. */
/* When the artifact panel (report agent, ...) opens, hide the launcher panels (they collide for
   horizontal space and break the layout — user request); restore on close. Class observation covers
   every open path. */
(function () {
  const art = document.getElementById('artifactPanel');
  if (!art || !window.MutationObserver) return;
  new MutationObserver(function () {
    const open = art.classList.contains('open');
    ['ai365FlpRes', 'ai365FlpGw', 'ai365FlpAuto', 'ai365FlpFlows'].forEach(function (id) {
      const el = document.getElementById(id);
      if (el) el.style.display = open ? 'none' : '';
    });
  }).observe(art, { attributes: true, attributeFilter: ['class'] });
})();

// 미리보기 상호작용 위임 — 컨테이너가 chatInner 안에 산다.
// 데이터 헤더=아코디언 토글, 지식 칩=파일 전환, 지식 헤더=접기(재렌더 없이 표시만 토글 — PDF 리로드 방지)
// Delegated preview interactions — data header = accordion toggle, knowledge chip = file switch,
// knowledge header = fold (display-only toggle, no re-render, so the PDF never reloads)
chatInner.addEventListener('click', function (e) {
  const hd = e.target.closest('[data-prevhd]');
  if (hd) {
    const k = hd.getAttribute('data-prevhd');
    AI365_FLP_PREV_OPENKEY = (AI365_FLP_PREV_OPENKEY === k) ? null : k;
    ai365FlpPrevSync('data');
    return;
  }
  const fold = e.target.closest('[data-kpfold]');
  if (fold) {
    AI365_FLP_KPREV_FOLD = !AI365_FLP_KPREV_FOLD;
    const card = fold.closest('.ai365-flprev-card');
    const kb = card && card.querySelector('.ai365-flprev-kbody');
    if (card) card.classList.toggle('open', !AI365_FLP_KPREV_FOLD);
    if (kb) kb.style.display = AI365_FLP_KPREV_FOLD ? 'none' : '';
    const box = document.getElementById('ai365FlpPrev');
    if (box && box.getAttribute('data-sig')) {
      box.setAttribute('data-sig', box.getAttribute('data-sig').replace(/::[01]$/, '::' + (AI365_FLP_KPREV_FOLD ? 1 : 0)));
    }
    return;
  }
  const chip = e.target.closest('[data-kprev]');
  if (!chip) return;
  const nm = chip.getAttribute('data-kprev');
  AI365_FLP_KPREV_CUR = (AI365_FLP_KPREV_CUR === nm) ? null : nm;   // 재클릭=뷰어 닫기 / re-click closes the viewer
  ai365FlpPrevSync('knowledge');
});

/* ═══════════════════════════════════════════════════════════════════════════
   에이전트 모드 — 그룹웨어 (2026-08-24, 4차 개편. 사용자 시안 15장 + 컴포넌트 스펙 2장)
   · 진입: 히어로(공유) + 우측 **"업무 관리"** 패널 = 오늘 업무 요약 KPI 3타일 + 도구 카드 5장
     (Outlook 메일·Outlook 일정·Teams·Microsoft To Do·SharePoint — [대화하기], 행 3개 + "N건 더 보기",
     행 펼침 → 액션 칩). 데이터는 GET /api/gwwork/panel(스마트 실행 시드와 같은 원천).
   · 칩 클릭 → 2줄 사용자 말풍선("도구 · 액션" / 항목) + 결과(카드 / 텍스트+카드 / 텍스트+카드+액션
     버튼) — POST /api/gwwork/ask 시드 응답(실 연동 때 내부만 교체). 카드 버튼은 로컬 연출.
     일정 변경은 2턴(후보 → "N번" 회신 → 변경 카드; ai365GwCardHandle이 simulateAiReply 체인에서 받음).
   · **패널은 대화 중에도 유지**(그룹웨어 모드에서 만든 채팅은 AI365_GW_CHATS에 등록 — 채팅 전환·
     새로고침 복원 후에도 패널이 따라온다). 펼친 행·누른 칩은 강조.
   · [대화하기] = 그 도구의 @액션모드 세션 시작(백엔드 채팅이 열려 있을 때) / 런처에서는 @도구 삽입.
   · 타이핑 질문이 그룹웨어 위젯을 호출하면(ai365GwHandle) 같은 에이전트 카드 프레임으로 답한다.
   Agent mode — Groupware (rework round 4; 15 reference designs + 2 component specs).
   Entry: shared hero + the right "Work management" panel = today's KPI tiles + five tool cards
   ([Chat], 3 rows + "N more", row expand → action chips). Data: GET /api/gwwork/panel (same source as
   the smart-execution seeds). Chip click → two-line user bubble ("tool · action" / item) + result
   (card / text+card / text+card+action button) from the seeded POST /api/gwwork/ask (real integration
   swaps only its inside); card buttons are local staging. Reschedule is two-turn ("N번" reply handled
   by ai365GwCardHandle in the simulateAiReply chain). The panel PERSISTS during the chat (chats
   created in this mode are registered in AI365_GW_CHATS and the panel follows them after switches and
   refresh). [Chat] = start that tool's @action-mode session (open backend chat) / insert @tool in the
   launcher. Typed questions that hit a groupware widget (ai365GwHandle) answer in the same agent-card frame.
═══════════════════════════════════════════════════════════════════════════ */
const AI365_GW_NS_ICON = {
  mail: '<span class="ic" style="background:#E8EEFE"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#4F6BF3" stroke-width="1.9" stroke-linejoin="round"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m4 7 8 6 8-6" stroke-linecap="round"/></svg></span>',
  calendar: '<span class="ic" style="background:#E8EEFE"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#4F6BF3" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M8 3v4M16 3v4M3 10h18"/></svg></span>',
  teams: '<span class="ic" style="background:#E8EEFE"><svg width="16" height="16" viewBox="0 0 24 24" fill="#4F6BF3"><circle cx="9" cy="8" r="3.2"/><circle cx="16.5" cy="9" r="2.4"/><path d="M3 19c0-3.3 2.7-6 6-6s6 2.7 6 6z"/><path d="M15.5 13.5c2.7 0 5 2.2 5 5h-4.2c0-1.9-.6-3.7-1.6-5z"/></svg></span>',
  todo: '<span class="ic" style="background:#E8EEFE"><svg width="16" height="16" viewBox="0 0 24 24" fill="#4F6BF3"><circle cx="12" cy="12" r="10"/><path d="m8.5 12.3 2.4 2.4 4.8-5" stroke="#fff" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span>',
  sharepoint: '<span class="ic" style="background:#E8EEFE"><svg width="16" height="16" viewBox="0 0 24 24" fill="#4F6BF3"><path d="M3 7a2 2 0 0 1 2-2h4l2 2.5h8a2 2 0 0 1 2 2V17a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg></span>',
};
const AI365_GW_BTN_DONE = { '전송': '전송됨', '추가': '추가됨', '열기': '열림' };
let AI365_GW_PANEL = null;        // { data, open:'ns:id'|null, more:{ns:true}, last:'ns:id:action'|null, err }
const AI365_GW_CHATS = {};        // chat_id → true (그룹웨어 모드 채팅 — 패널 유지) / groupware-mode chats (panel persists)
const AI365_GW_PENDING = {};      // chat_id → pending(일정 변경 2턴) / two-turn reschedule state
let AI365_GW_NEXT = false;        // 런처 타이핑 전송 → 생성될 채팅을 그룹웨어 모드로 / typed launcher send → register the new chat
// 패널 탭(2026-09-03 사용자 지시 1단계): '업무 관리' | '보안 에이전트' — 보안 탭은 우선 전환만(내용은 자리표시자)
// Panel tab (user request, step 1): 'work' | 'security' — the security tab only switches for now (placeholder body)
let AI365_GW_TAB = 'work';

function ai365GwPanelEl() {
  const p = document.createElement('aside');
  p.className = 'ai365-flp';
  p.id = 'ai365FlpGw';
  p.innerHTML = '<div class="ai365-agp-tabs">'
    + '<button type="button" class="ai365-agp-tab on" data-agptab="work">' + ai365T('업무 관리') + '</button>'
    + '<button type="button" class="ai365-agp-tab" data-agptab="security">' + ai365T('보안 에이전트') + '</button></div>'
    + '<div class="ai365-flp-body" id="ai365GwBody"><div class="think-row"><span class="spinner"></span>' + ai365T('불러오는 중…') + '</div></div>'
    + '<div class="ai365-flp-body" id="ai365GwSecBody" style="display:none"><div class="ai365-fl-none">' + ai365T('보안 에이전트 화면은 준비 중입니다.') + '</div></div>';
  p.addEventListener('click', ai365GwPanelClick);
  ai365GwTabSet(AI365_GW_TAB, p);   // 재생성 시 마지막 탭 유지 / keep the last tab when the panel is rebuilt
  return p;
}

/* 탭 전환 — 탭 강조 + 본문 컨테이너 표시 토글(업무 관리 본문은 ai365GwRender가 그대로 채운다) */
/* Tab switch — highlight + toggle the body containers (the work body is still filled by ai365GwRender) */
function ai365GwTabSet(tab, root) {
  AI365_GW_TAB = tab === 'security' ? 'security' : 'work';
  const p = root || document.getElementById('ai365FlpGw');
  if (!p) return;
  p.querySelectorAll('.ai365-agp-tab').forEach(function (t) { t.classList.toggle('on', t.getAttribute('data-agptab') === AI365_GW_TAB); });
  const w = p.querySelector('#ai365GwBody'), s = p.querySelector('#ai365GwSecBody');
  if (w) w.style.display = AI365_GW_TAB === 'work' ? '' : 'none';
  if (s) s.style.display = AI365_GW_TAB === 'security' ? '' : 'none';
}

/* 패널 열기(멱등) — 런처 진입·그룹웨어 채팅 복귀·복원에서 호출. 이미 있으면 재렌더만. */
/* Open the panel (idempotent) — launcher entry, return to a groupware chat, restore. Re-renders if present. */
function ai365GwPanelOpen() {
  const body = document.querySelector('#viewChat .chat-body');
  if (!body) return;
  if (!document.getElementById('ai365FlpGw')) {
    const art = document.getElementById('artifactPanel');
    const p = ai365GwPanelEl();
    if (art) body.insertBefore(p, art); else body.appendChild(p);
  }
  if (AI365_GW_PANEL && AI365_GW_PANEL.data) { ai365GwRender(); return; }
  ai365GwLoad();
}

function ai365GwLoad() {
  const st = AI365_GW_PANEL && AI365_GW_PANEL.data ? AI365_GW_PANEL : { data: null, open: null, more: {}, last: null, err: false };
  AI365_GW_PANEL = st;
  fetch('/api/gwwork/panel')
    .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(function (d) { if (AI365_GW_PANEL !== st) return; st.data = d; st.err = false; ai365GwRender(); })
    .catch(function () { if (AI365_GW_PANEL !== st) return; st.err = true; ai365GwRender(); });
}

function ai365GwBold(s) {
  return ai365Esc(String(s || '')).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
}

function ai365GwRender() {
  const el = document.getElementById('ai365GwBody');
  const st = AI365_GW_PANEL;
  if (!el || !st) return;
  if (st.err) { el.innerHTML = '<div class="ai365-fl-none">' + ai365T('불러오지 못했습니다') + '</div>'; return; }
  if (!st.data) return;
  const d = st.data;
  let h = '<div class="ai365-gw-kpi-tt">' + ai365T('오늘 업무 요약') + '</div><div class="ai365-gw-kpis">'
    + (d.kpi || []).map(function (k) { return '<div class="ai365-gw-kpi"><span>' + ai365Esc(ai365T(k.label)) + '</span><b>' + ai365Esc(k.value) + '</b></div>'; }).join('')
    + '</div>';
  (d.tools || []).forEach(function (t) {
    const rows = t.rows || [];
    const expanded = !!st.more[t.ns];
    const shown = expanded ? rows : rows.slice(0, 3);
    h += '<div class="ai365-gw-tool" data-gw-ns="' + t.ns + '">'
      + '<div class="ai365-gw-tool-hd">' + (AI365_GW_NS_ICON[t.ns] || '') + '<span class="ai365-gw-tool-tx"><b>' + ai365Esc(ai365T(t.label)) + '</b><i>' + ai365GwBold(t.sub) + '</i></span>'
      + '<button type="button" class="ai365-gw-talk" data-gw-talk="' + t.ns + '">' + ai365T('대화하기') + '</button></div>';
    shown.forEach(function (r) {
      const key = t.ns + ':' + r.id;
      const open = st.open === key;
      h += '<div class="ai365-gw-row' + (open ? ' open' : '') + '" data-gw-row="' + ai365Esc(key) + '">'
        + '<span class="ai365-gw-time">' + ai365Esc(r.time || '') + '</span>'
        + '<span class="ai365-gw-main"><b>' + ai365Esc(r.title) + '</b><i>' + ai365Esc(r.sub || '') + '</i></span>'
        + '<span class="ai365-gw-chev">' + AI365_FLP_PREV_CARET + '</span></div>';
      if (open) {
        h += '<div class="ai365-gw-acts">' + (t.actions || []).map(function (a) {
          const on = st.last === key + ':' + a.key;
          return '<button type="button" class="ai365-gw-chip' + (on ? ' on' : '') + '" data-gw-act="' + ai365Esc(key + ':' + a.key) + '">' + ai365Esc(ai365T(a.label)) + '</button>';
        }).join('') + '</div>';
      }
    });
    if (rows.length > 3 || expanded) {
      h += '<div class="ai365-gw-more" data-gw-more="' + t.ns + '">' + (expanded ? ai365T('접기') : ai365Esc(ai365T(t.more || '더 보기')))
        + '<span class="ai365-gw-chev"' + (expanded ? ' style="transform:rotate(180deg)"' : '') + '>' + AI365_FLP_PREV_CARET + '</span></div>';
    }
    h += '</div>';
  });
  el.innerHTML = h;
}

function ai365GwPanelClick(e) {
  // 탭 클릭은 데이터 로드 여부와 무관하게 전환 / tab clicks switch regardless of data load state
  const tab = e.target.closest('[data-agptab]');
  if (tab) { ai365GwTabSet(tab.getAttribute('data-agptab')); return; }
  const st = AI365_GW_PANEL;
  if (!st || !st.data) return;
  const talk = e.target.closest('[data-gw-talk]');
  if (talk) { ai365GwTalk(talk.getAttribute('data-gw-talk')); return; }
  const act = e.target.closest('[data-gw-act]');
  if (act) {
    const p = act.getAttribute('data-gw-act').split(':');   // ns:id:action
    st.last = act.getAttribute('data-gw-act');
    ai365GwRender();
    ai365GwAct(p[0], p[1], p[2]);
    return;
  }
  const row = e.target.closest('[data-gw-row]');
  if (row) {
    const k = row.getAttribute('data-gw-row');
    st.open = (st.open === k) ? null : k;
    ai365GwRender();
    return;
  }
  const more = e.target.closest('[data-gw-more]');
  if (more) {
    const ns = more.getAttribute('data-gw-more');
    st.more[ns] = !st.more[ns];
    ai365GwRender();
  }
}

/* [대화하기] — 백엔드 채팅이 열려 있으면 그 도구의 @액션모드 세션(남색 바), 런처에서는 @도구 삽입 */
/* [Chat] — with an open backend chat start that tool's @action-mode session; in the launcher insert the @tool */
function ai365GwTalk(ns) {
  const inChat = typeof currentChatId !== 'undefined' && currentChatId && AI365_BACKEND_IDS.has(currentChatId);
  if (inChat && typeof ai365MnSessStart === 'function') {
    ai365MnSessStart(ns);
    if (typeof ai365MnRenderSessBar === 'function') ai365MnRenderSessBar();
  } else if (typeof ai365MnInsert === 'function') {
    ai365MnInsert(ns);
  }
  const inp = document.getElementById('chatInput');
  if (inp) inp.focus();
}

/* ── 결과 렌더 ── */
/* ── Result rendering ── */
function ai365GwUserBubbleHtml(text) {
  const parts = String(text || '').split('\n');
  return '<div class="msg msg-user appear"><div class="user-bubble ai365-gw-ub"><b>' + ai365Esc(parts[0] || '') + '</b>'
    + (parts[1] ? '<span>' + ai365Esc(parts.slice(1).join(' ')) + '</span>' : '') + '</div></div>';
}

function ai365GwInline(s) {
  let h = ai365Esc(String(s || ''));
  h = h.replace(/\*\*(.+?)\*\*/g, '<b>$1</b>');
  h = h.replace(/\[([^\]]+)\]\(([^)]+)\)/g, function (m, t, u) {
    const safe = /^(https?:\/\/|#)/.test(u) ? u : '#';
    return '<a href="' + ai365Esc(safe) + '" target="_blank" rel="noopener">' + t + '</a>';
  });
  return h;
}

function ai365GwLinesHtml(lines) {
  let h = '', ul = [];
  const flush = function () { if (ul.length) { h += '<ul>' + ul.map(function (x) { return '<li>' + ai365GwInline(x) + '</li>'; }).join('') + '</ul>'; ul = []; } };
  (lines || []).forEach(function (l) {
    const s = String(l || '');
    if (s.indexOf('- ') === 0) { ul.push(s.slice(2)); return; }
    flush();
    if (!s.trim()) { h += '<div class="ai365-gw-gap"></div>'; return; }
    h += '<p>' + ai365GwInline(s) + '</p>';
  });
  flush();
  return h;
}

function ai365GwCardHtml(card) {
  if (!card) return '';
  return '<div class="ai365-gw-card"><div class="ai365-gw-card-hd">' + (AI365_GW_NS_ICON[card.ns] || '')
    + '<b>' + ai365Esc(card.title || '') + '</b>'
    + (card.btn ? '<button type="button" class="ai365-gw-btn" data-gw-btn="' + ai365Esc(card.btn) + '">' + ai365Esc(ai365T(card.btn)) + '</button>' : '')
    + '</div><div class="ai365-gw-card-bd">' + ai365GwLinesHtml(card.lines) + '</div></div>';
}

function ai365GwAnswerHtml(text, card) {
  return aiHead('', false) + (text ? '<div class="ai365-gw-text">' + ai365Esc(text) + '</div>' : '') + ai365GwCardHtml(card);
}

/* 복원 — gw_card 메시지(ai365AppendAssistant에서 호출). 채팅을 그룹웨어 모드로 등록하고 패널을 붙인다. */
/* Restore — gw_card messages (called from ai365AppendAssistant). Registers the chat and attaches the panel. */
function ai365GwCardEl(meta) {
  const wrap = document.createElement('div');
  wrap.className = 'msg msg-ai ai365-gw-msg';
  wrap.innerHTML = ai365GwAnswerHtml(meta.text || '', meta.card) + FOOT;
  if (currentChatId) {
    AI365_GW_CHATS[currentChatId] = true;
    AI365_GW_PENDING[currentChatId] = meta.pending || null;
    setTimeout(ai365GwPanelOpen, 0);
  }
  return wrap;
}

/* 행 액션 실행 — 런처면 /ask가 채팅을 만들고(패널 유지), 채팅 중이면 이어 붙인다 */
/* Run a row action — in the launcher /ask creates the chat (panel stays); in a chat it appends */
function ai365GwAct(ns, itemId, action, choice) {
  if (typeof replyActive !== 'undefined' && replyActive) { if (typeof toast === 'function') toast(ai365T('답변이 끝난 뒤 실행해 주세요.')); return; }
  const launcher = AI365_FLOW_LAUNCH === 'groupware' && !currentChatId && !!chatInner.querySelector('.ai365-fl-pre');
  const cid = launcher ? '' : (currentChatId && AI365_BACKEND_IDS.has(currentChatId) ? currentChatId : '');
  if (!launcher && !cid) { if (typeof toast === 'function') toast(ai365T('이 채팅에서는 실행할 수 없습니다.')); return; }
  if (launcher) {
    AI365_FLOW_LAUNCH = null;
    chatInner.innerHTML = '';
    currentChatId = null;
  }
  const wrap = document.createElement('div');
  wrap.className = 'msg msg-ai appear ai365-gw-msg';
  wrap.innerHTML = '<div class="think-row"><span class="spinner"></span>' + ai365T('처리 중입니다') + '</div>';
  let bubble = null;
  if (action !== 'reschedule_apply') {
    const holder = document.createElement('div');
    holder.innerHTML = ai365GwUserBubbleHtml('…');
    bubble = holder.firstChild;
    chatInner.appendChild(bubble);
  }
  chatInner.appendChild(wrap);
  if (typeof stickToBottom === 'function') stickToBottom();
  ai365SetSending(true);
  // 스트림이 다른 채팅에서 도는 중이면 sending을 건드리지 않는다(ai365GwHandle과 같은 계약, 리뷰 확정)
  // Never release sending while an SSE stream runs elsewhere (same contract as ai365GwHandle)
  const unlock = function () { if (!ai365Abort) ai365SetSending(false); };
  ai365Fetch('/api/gwwork/ask', {
    method: 'POST', headers: AI365_JSON_HEADERS,
    body: JSON.stringify({ ns: ns, item_id: itemId, action: action, chat_id: cid, choice: choice || 0 }),
  })
    .then(function (d) {
      if (launcher) {
        AI365_BACKEND_IDS.add(d.chat_id);
        chats.push({ id: d.chat_id, title: d.title, pinned: false, conv: 'blank', scope: '자동', knowledge: null, docSearch: false, _backend: true, sched: null });
        if (wrap.isConnected) {
          currentChatId = d.chat_id;
          $('#chatTitle').textContent = d.title;
          $('#chatTitle').title = d.title;
          if (typeof ai365SetScopeLabel === 'function') ai365SetScopeLabel('자동');
        }
        renderChatLists();
      }
      AI365_GW_CHATS[d.chat_id] = true;
      AI365_GW_PENDING[d.chat_id] = d.pending || null;
      if (!wrap.isConnected) { unlock(); return; }
      if (bubble) bubble.outerHTML = ai365GwUserBubbleHtml(d.user || '');
      wrap.innerHTML = ai365GwAnswerHtml(d.text || '', d.card) + FOOT;
      unlock();
      if (typeof stickToBottom === 'function') stickToBottom();
    })
    .catch(function () {
      if (wrap.isConnected) wrap.innerHTML = '<div class="think-row">' + ai365T('불러오지 못했습니다') + '</div>';
      if (bubble && bubble.isConnected) bubble.remove();
      unlock();
    });
}

/* 2턴 회신("2번") — simulateAiReply 체인에서 호출. 목업이 이미 사용자 말풍선을 찍은 뒤다. */
/* Two-turn reply ("2번") — called from the simulateAiReply chain, after the mockup posted the user bubble */
function ai365GwCardHandle(text) {
  if (!currentChatId || !AI365_GW_PENDING[currentChatId]) return false;
  const p = AI365_GW_PENDING[currentChatId];
  const m = String(text || '').match(/^\s*(\d)\s*번?\s*$/);
  const n = m ? parseInt(m[1], 10) : 0;
  // 후보 번호가 아닌 다른 턴이면 대기 해제 — 나중의 한 자리 숫자 답이 하이재킹되지 않게(리뷰 확정)
  // Any other turn cancels the pending so a later single-digit reply is never hijacked (review finding)
  if (!(n >= 1 && n <= (p.options || []).length)) { AI365_GW_PENDING[currentChatId] = null; return false; }
  ai365GwAct(p.ns, p.item_id, 'reschedule_apply', n);
  return true;
}

/* 위젯 질의 답(ai365GwHandle) — 에이전트 카드 프레임으로(사용자: "에이전트가 호출되면 카드") */
/* Widget-query answers (ai365GwHandle) — in the agent-card frame (user: "a card whenever an agent is called") */
function ai365GwWidgetFrameHtml(label) {
  const lines = [{ text: (label ? label + ' ' : '') + '위젯을 조회했습니다', done: true, raw: true }, { text: '결과를 정리했습니다', done: true, raw: true }];
  const groups = [{ label: ai365T('그룹웨어 위젯을 조회했습니다.'), lines: [ai365T('조회 결과를 카드로 정리했습니다.')] }];
  return aiHead('', false)
    + '<div class="ai365-agx-scnt">' + ai365T('사내 리소스 1개') + '</div>'
    + '<div class="ai365-kx-box"><div class="ai365-kx-card">' + (AI365_RES_ICONS.work || '')
    + '<span class="ai365-kx-card-tx"><b>' + ai365T('그룹웨어 에이전트') + '</b><i class="ai365-kx-sub">' + ai365Esc(label || ai365T('위젯 조회')) + '</i></span></div>'
    + '<div class="ai365-kx-prog"><div class="ai365-kx-lines">' + lines.map(ai365KxLineHtml).join('') + '</div></div></div>'
    + ai365KxThinkHtml(groups, false);
}

document.addEventListener('click', function (e) {
  const b = e.target.closest('[data-gw-btn]');
  if (!b || b.disabled) return;
  const label = b.getAttribute('data-gw-btn') || '';
  let done = '';
  Object.keys(AI365_GW_BTN_DONE).forEach(function (k) { if (label.indexOf(k) >= 0) done = AI365_GW_BTN_DONE[k]; });
  b.textContent = ai365T(done || '완료');
  b.disabled = true;
  b.classList.add('done');
  if (typeof toast === 'function') toast(ai365T(label) + ' — ' + ai365T('데모에서는 실제 전송되지 않습니다.'));
});

/* 생명주기 합성 — 채팅 전환·복원 후 그룹웨어 모드 채팅이면 패널을 다시 붙인다; 런처 타이핑 전송으로
   생긴 채팅도 등록한다. */
/* Lifecycle — re-attach the panel after chat switches/restores for groupware-mode chats; register chats
   created by a typed launcher send. */
(function () {
  const prevOpen = openChat;
  openChat = function (chatId, opts) {
    prevOpen(chatId, opts === undefined ? {} : opts);
    if (AI365_GW_CHATS[chatId]) setTimeout(ai365GwPanelOpen, 0);
  };
  // 임베드(그룹웨어/교육 인앱 뷰)에서 채팅으로 복귀해도 그룹웨어 채팅이면 패널 유지(리뷰 확정)
  // Returning to chat from an in-app embed keeps the panel for groupware chats (review finding)
  const prevSV = window.showView;
  window.showView = function (name) {
    const r = prevSV.apply(this, arguments);
    if (name === 'chat' && !AI365_FLOW_LAUNCH && typeof currentChatId !== 'undefined' && currentChatId
        && AI365_GW_CHATS[currentChatId] && !document.getElementById('ai365FlpGw')) setTimeout(ai365GwPanelOpen, 0);
    return r;
  };
  const prevBlank = openBlankChat;
  openBlankChat = function (firstMessage, opts) {
    const want = AI365_GW_NEXT;
    AI365_GW_NEXT = false;
    // 기존 채팅 id 스냅숏 — 생성 대기 중 다른 채팅을 열어도 그 채팅이 등록되지 않게(리뷰 확정)
    // Snapshot existing ids — opening another chat while waiting must never register it (review finding)
    const before = new Set(AI365_BACKEND_IDS);
    const r = prevBlank(firstMessage, opts);
    if (want) {
      let n = 0;
      const iv = setInterval(function () {
        n++;
        if (currentChatId && AI365_BACKEND_IDS.has(currentChatId) && !before.has(currentChatId) && !AI365_FLOW_LAUNCH) {
          clearInterval(iv);
          AI365_GW_CHATS[currentChatId] = true;
          ai365GwPanelOpen();
        } else if (n > 75 || (currentChatId && before.has(currentChatId))) clearInterval(iv);
      }, 200);
    }
    return r;
  };
})();

