/* 진행줄 문구 — 완료된 줄은 과거형으로("…하고 있습니다"→"…했습니다"), 영어는 사전 번역 그대로 */
/* Progress copy — finished lines switch to past tense (Korean); English keeps the dictionary label */
function ai365KxLineText(line) {
  // 로컬 줄(2026-09-30)은 에이전트 이름이 든 서버 문구라 언어와 무관하게 원문, 시작 줄("…질문하고 있습니다 · 이름")만 과거형으로
  // Local lines (2026-09-30) are server text with agent names, shown as sent in any language; only the start line turns past tense
  if (line.local) return line.done ? String(line.text).replace('질문하고 있습니다', '질문했습니다') : String(line.text);
  if (ai365KxEn()) return ai365T(line.text);
  if (line.done && !line.raw) return String(line.text).replace(/하고 있습니다\.?$/, '했습니다');
  return String(line.text);
}

/* ── 프레임 상태: kx = { title, cards:[{agent, lines, folders, files, resources, groups}], web:{lines,ext}|null,
   local:{lines,items}|null, common:[lines], sid, fold, bi } — 단독 라우팅은 카드 1장, 병렬은 호출된 에이전트 수만큼 ── */
/* ── Frame state: one card per called agent; web = the pipeline's web-supplement card; local = the local-knowledge card
   (2026-09-30); common = shared stages ── */
function ai365KxCard(agent) {
  const sc = ai365KxScopeCounts(agent);
  // 로컬 전용(리소스 선택의 Local, 2026-10-28): Public 검색 문구 없이 시작한다 / local only (the picker's Local): no Public search copy
  const localOnly = agent === 'knowledge' && sc.local > 0;
  return { agent: agent, lines: [], folders: sc.folders, files: sc.files, resources: sc.resources, local: sc.local || 0, localOnly: localOnly,
    groups: localOnly ? [] : ai365KxGroupsFromNames(agent, sc.names) };
}

function ai365KxAllLists(kx) {
  const ls = kx.cards.map(function (c) { return c.lines; });
  if (kx.local) ls.push(kx.local.lines);
  if (kx.web) ls.push(kx.web.lines);
  ls.push(kx.common);
  return ls;
}

function ai365KxPush(list, text, done, extra) {
  list.forEach(function (l) { l.done = true; });
  list.push(Object.assign({ text: text, done: !!done }, extra || {}));
}

/* 공통 단계(thinking) — "로컬"로 시작하는 줄은 로컬 지식 카드로(2026-09-30), 웹 관련 문구는 웹 검색 카드로, 나머지는 취합 줄로.
   새 공통 줄은 모든 대기 줄을 닫는다(에이전트 실행이 끝난 뒤에만 오는 단계). */
/* Shared stages (thinking) — lines starting with "로컬" go to the local-knowledge card (2026-09-30), web-related copy to the
   web card, the rest to the aggregation lines. A new shared line settles every pending line (these stages only arrive after
   the agents finish). */
function ai365KxLine(state, text, done, extra) {
  const kx = state.kx;
  if (!kx || !text) return;
  ai365KxAllLists(kx).forEach(function (ls) { ls.forEach(function (l) { l.done = true; }); });
  if (AI365_KX_LOCAL_RE.test(text)) {
    if (!kx.local) kx.local = { lines: [], items: [] };
    const settled = !/하고 있습니다/.test(text);   // 결과 줄(답변 확보 · 못 찾음 · 연결 실패)은 바로 완료 / result lines settle at once
    kx.local.lines.push(Object.assign({ text: text, done: settled || !!done, local: true, fail: /연결 실패/.test(text) }, extra || {}));
  } else if (AI365_KX_WEB_RE.test(text)) {
    if (!kx.web) kx.web = { lines: [], ext: [] };
    kx.web.lines.push(Object.assign({ text: text, done: !!done }, extra || {}));
  } else {
    kx.common.push(Object.assign({ text: text, done: !!done }, extra || {}));
  }
}

/* 검색 범위(체크 상태)에서 카드 수치·초기 think 그룹을 만든다 — done.sources가 오면 실제 참조 리소스로 확정 */
/* Card counts and initial think groups come from the checked scope — settled to referenced resources on done.sources */
function ai365KxScopeCounts(agent) {
  const H = window.AI365_SMF_HOOKS;
  const sc = (H && H.scope && H.scope()) || {};
  if (agent === 'data') {
    const names = [];
    (sc.data_tables || []).forEach(function (t) { const m = ai365FlpTableMeta(t); names.push({ label: m.label, kind: m.kind }); });
    (sc.data_bi || []).forEach(function (f) { names.push({ label: ai365FlpBiLabel(f), kind: 'BI' }); });
    return { folders: 0, files: 0, resources: names.length, names: names };
  }
  if (agent === 'work') return { folders: 0, files: 0, resources: 1, names: [] };
  // 그룹웨어는 워크플로우 실행에서만 카드로 뜬다 — 컴포저 스코프와 무관하므로 sources로만 확정
  // Groupware only appears as a card in workflow runs — unrelated to composer scope, settled by sources
  if (agent === 'groupware') return { folders: 0, files: 0, resources: 0, names: [] };
  const keys = H ? H.files() : [];
  const names = (sc.knowledge_files || []).slice();
  // local:<id> = 리소스 선택의 Local 가짜 키(static/resource_select.js) / the resource picker's Local pseudo keys
  const local = keys.filter(function (k) { return k.indexOf('local:') === 0; }).length;
  return { folders: keys.filter(function (k) { return k.indexOf('kn:') === 0; }).length, files: names.length, resources: 0, names: names, local: local };
}

function ai365KxSubLabel(card) {
  const en = ai365KxEn();
  if (card.agent === 'work') return ai365T('업무 자동화');
  if (card.agent === 'groupware') {
    if (!card.resources) return ai365T('그룹웨어');
    return en ? ('Resources ' + card.resources) : ('리소스 ' + card.resources);
  }
  if (card.agent === 'data') {
    if (!card.resources) return ai365T('전체 데이터');
    return en ? ('Resources ' + card.resources) : ('리소스 ' + card.resources);
  }
  if (card.agent === 'api') return ai365T('API 호출');   // API 작업 카드(2026-09-11): 문서 수 대신 호출 표식 / API task card shows a call marker, not document counts
  if (card.localOnly) return card.local ? (en ? ('Local · Agents ' + card.local) : ('Local · 에이전트 ' + card.local)) : 'Local';
  if (!card.files && !card.folders) return ai365T('전체 문서');
  return en ? ('Folders ' + card.folders + ' · Files ' + card.files) : ('폴더 ' + card.folders + ' · 파일 ' + card.files);
}

function ai365KxFinalGroup(agent, past) {
  // API 작업(2026-09-11): 문단 검색이 아니라 응답 정리 문구 / API task: response-shaping copy instead of passage search
  if (agent === 'api') {
    return past ? { label: ai365T('API 응답을 정리했습니다.'), lines: [ai365T('응답 결과를 바탕으로 요약 내용을 생성했습니다.')] }
      : { label: ai365T('API 응답을 정리합니다.'), lines: [ai365T('사용자 요청에 맞춰 응답 내용을 정리합니다.')] };
  }
  if (agent === 'data') {
    return past ? { label: ai365T('분석 결과를 통합했습니다.'), lines: [ai365T('분석 결과를 바탕으로 요약 내용을 생성했습니다.')] }
      : { label: ai365T('분석 결과를 통합합니다.'), lines: [ai365T('사용자 요청에 맞춰 분석 결과를 생성합니다.')] };
  }
  return past ? { label: ai365T('검색 결과를 통합했습니다.'), lines: [ai365T('참조 문단을 바탕으로 요약 내용을 생성했습니다.')] }
    : { label: ai365T('검색 결과를 통합합니다.'), lines: [ai365T('사용자 요청에 맞춰 요약 내용을 생성합니다.')] };
}

function ai365KxGroupsFromNames(agent, names) {
  const en = ai365KxEn();
  const g = [];
  if (agent === 'work') {
    g.push({ label: ai365T('업무 자동화 에이전트가 관련 자료를 조회합니다.'), lines: [ai365T('관련 자료와 요청 내용을 확인합니다.')] });
    g.push(ai365KxFinalGroup('knowledge', false));
    return g;
  }
  if (agent === 'groupware') {
    g.push({ label: ai365T('그룹웨어 자료를 조회합니다.'), lines: [ai365T('일정·조직도 등 관련 자료를 확인합니다.')] });
    g.push(ai365KxFinalGroup('knowledge', false));
    return g;
  }
  if (agent === 'api') {
    // API 작업(2026-09-11): 입력값 추출 → 호출 → 응답 정리 / API task: extract inputs → call → shape the response
    g.push({ label: ai365T('API 호출 조건을 정리합니다.'), lines: [ai365T('요청과 앞 단계 결과에서 필요한 입력값을 뽑습니다.')] });
    g.push(ai365KxFinalGroup('api', false));
    return g;
  }
  if (agent === 'data') {
    if (names && names.length) {
      names.slice(0, 3).forEach(function (n) {
        g.push({ label: n.kind === 'BI'
          ? ai365KxBiPhrase(n.label, false)
          : (en ? ('Querying ' + n.label + ' (' + n.kind + ')') : (n.label + ' ' + n.kind + '를 조회합니다.')),
          lines: [ai365T(n.kind === 'BI' ? '대시보드 지표를 확인합니다.' : '분석 쿼리를 실행합니다.')] });
      });
      if (names.length > 3) g.push({ label: en ? ('Querying ' + (names.length - 3) + ' more resources') : ('외 ' + (names.length - 3) + '건의 리소스를 조회합니다.'), lines: [ai365T('분석 쿼리를 실행합니다.')] });
    } else {
      g.push({ label: ai365T('데이터 분석 자료를 조회합니다.'), lines: [ai365T('권한 범위의 데이터에서 분석 쿼리를 실행합니다.')] });
    }
    g.push(ai365KxFinalGroup('data', false));
    return g;
  }
  if (names && names.length) {
    names.slice(0, 3).forEach(function (n) {
      g.push({ label: en ? ('Checking related content in ' + n) : (n + '에서 관련 내용을 확인합니다.'), lines: [ai365T('질문과 관련된 문단을 검색합니다.')] });
    });
    if (names.length > 3) g.push({ label: en ? ('Searching ' + (names.length - 3) + ' more documents') : ('외 ' + (names.length - 3) + '건의 문서를 검색합니다.'), lines: [ai365T('질문과 관련된 문단을 검색합니다.')] });
  } else {
    g.push({ label: ai365T('지식 관리 자료를 검색합니다.'), lines: [ai365T('권한 범위의 문서에서 관련 문단을 검색합니다.')] });
  }
  g.push(ai365KxFinalGroup('knowledge', false));
  return g;
}

/* BI 문구 — 라벨이 이미 "…대시보드"로 끝나면 단어를 겹치지 않는다 / avoid "대시보드 대시보드" when the label already ends with it */
function ai365KxBiPhrase(label, past) {
  const en = ai365KxEn();
  if (en) return (past ? 'Analyzed the ' : 'Analyzing the ') + label + (/dashboard$/i.test(label) ? '' : ' dashboard');
  const base = /대시보드$/.test(label) ? label : (label + ' 대시보드');
  return base + (past ? '를 분석했습니다.' : '를 분석합니다.');
}

function ai365KxItemKind(it) {
  if (!it) return 'DB';
  if (it.kind === 'bi') return 'BI';
  const last = (it.path || [])[(it.path || []).length - 1];
  return (last === 'CSV' || last === 'DB') ? last : 'DB';
}

function ai365KxGroupsFromSources(agent, sources) {
  const en = ai365KxEn();
  if (agent === 'work') {
    const w = sources && sources.work;
    if (!w) return null;
    return [{ label: ai365T('업무 자동화 에이전트가 관련 자료를 조회했습니다.'), lines: [ai365T('관련 자료와 요청 내용을 확인했습니다.')] },
      ai365KxFinalGroup('knowledge', true)];
  }
  if (agent === 'groupware') {
    const w = sources && sources.groupware;
    if (!w || !(w.items || []).length) return null;
    const g = (w.items || []).slice(0, 6).map(function (it) {
      const lines = [en ? ('Checked ' + it.title) : (it.title + ' 자료를 확인했습니다.')];
      if (it.path && it.path.length) lines.push(it.path.join(' > '));
      return { label: en ? ('Checked ' + it.title) : (it.title + '을(를) 확인했습니다.'), lines: lines };
    });
    g.push(ai365KxFinalGroup('knowledge', true));
    return g;
  }
  if (agent === 'data') {
    const d = sources && sources.data;
    if (!d || !(d.items || []).length) return null;
    const g = ai365KxDocList('data', d.items).slice(0, 6).map(function (it) {
      const lines = [];
      lines.push(ai365T(it.kind === 'bi' ? '대시보드 지표를 확인했습니다.' : 'SQL 실행 결과를 집계했습니다.'));
      if (it.path && it.path.length) lines.push(it.path.join(' > '));
      return { label: it.kind === 'bi'
        ? ai365KxBiPhrase(it.title, true)
        : (en ? ('Queried ' + it.title + ' (' + it.typeKind + ')') : (it.title + ' ' + it.typeKind + '를 조회했습니다.')), lines: lines };
    });
    g.push(ai365KxFinalGroup('data', true));
    return g;
  }
  const k = sources && sources.knowledge;
  if (!k || !(k.items || []).length) return null;
  const byDoc = [];
  (k.items || []).forEach(function (it) {
    let d = byDoc.find(function (x) { return x.title === it.title; });
    if (!d) { d = { title: it.title, pages: [], path: it.path || [] }; byDoc.push(d); }
    if (it.page != null && d.pages.indexOf(it.page) < 0) d.pages.push(it.page);
  });
  const g = byDoc.slice(0, 6).map(function (d) {
    const lines = [];
    if (d.pages.length) lines.push(en ? ('Referenced paragraphs on p.' + d.pages.join(', p.')) : ('p.' + d.pages.join(', p.') + ' 문단을 참조했습니다.'));
    if (d.path && d.path.length) lines.push(d.path.join(' > '));
    return { label: en ? ('Checked related content in ' + d.title) : (d.title + '에서 관련 내용을 확인했습니다.'), lines: lines };
  });
  if (byDoc.length > 6) g.push({ label: en ? ((byDoc.length - 6) + ' more documents referenced') : ('외 ' + (byDoc.length - 6) + '건의 문서를 참조했습니다.'), lines: [] });
  g.push(ai365KxFinalGroup('knowledge', true));
  return g;
}

/* 전체 think 그룹 — 카드 1장이면 그대로, 여러 장이면 카드별 '통합' 그룹을 빼고 끝에 하나만 둔다 */
/* All think groups — one card: as is; several: drop each card's final group and keep a single shared one */
function ai365KxAllGroups(kx) {
  if (kx.cards.length <= 1) {
    const c = kx.cards[0];
    return c ? c.groups : [];
  }
  let out = [];
  kx.cards.forEach(function (c) {
    const g = (c.groups || []).slice();
    if (g.length > 1) g.pop();
    out = out.concat(g);
  });
  const past = kx.cards.every(function (c) { return c.lines.length && c.lines.every(function (l) { return l.done; }); });
  out.push(ai365KxFinalGroup(kx.cards.some(function (c) { return c.agent === 'data'; }) && !kx.cards.some(function (c) { return c.agent === 'knowledge'; }) ? 'data' : 'knowledge', past));
  return out;
}

function ai365KxThinkHtml(groups, fold, gfold) {
  if (!groups || !groups.length) return '';
  let h = '<div class="ai365-agx-think' + (fold ? ' fold' : '') + '">'
    + '<div class="ai365-agx-tkhd" data-agxfold="root">' + AI365_AGX_BRANCH_IC + '<span>' + ai365T('작업을 병렬로 실행') + '</span>' + AI365_AGX_CHEV_IC + '</div>'
    + '<div class="ai365-agx-tkbody">';
  groups.forEach(function (g, i) {
    h += '<div class="ai365-agx-tkgrp' + (gfold && gfold[i] ? ' fold' : '') + '"><div class="ai365-agx-tkghd" data-agxfold>' + AI365_AGX_ARROW_IC + '<span>' + ai365Esc(g.label || '') + '</span>' + AI365_AGX_CHEV_IC + '</div>'
      + '<div class="ai365-agx-tkglines">'
      + (g.lines || []).map(function (l) { return '<div class="ai365-agx-tkline">' + AI365_AGX_ARROW_IC + '<span>' + ai365Esc(l) + '</span></div>'; }).join('')
      + '</div></div>';
  });
  return h + '</div></div>';
}

function ai365KxLineHtml(line) {
  const ic = line.fail ? AI365_KX_FAIL_IC : (line.done ? AI365_AGX_TASK_IC : AI365_KX_PEND_IC);
  return '<div class="ai365-kx-line' + (line.done ? ' done' : ' pend') + (line.fail ? ' fail' : '') + '">' + ic
    + '<span>' + ai365Esc(ai365KxLineText(line)) + (line.done || line.fail ? '' : '..') + '</span></div>';
}

/* 외부 출처 칩 — 기존 리소스 블록 칩 마크업 재사용(리뷰 확정) / external-source chips — reuses the resource-block chip markup */
function ai365KxExtChips(ext, sid) {
  if (!ext || !ext.length) return '';
  let h = '<div class="ai365-res-chips">';
  ext.slice(0, 4).forEach(function (x) {
    h += '<button type="button" class="ai365-res-chip" data-ai365-exturl="' + ai365Esc(x.url || '') + '" title="' + ai365Esc(x.title || '') + '">🌐 ' + ai365Esc(x.title || x.url || '웹 출처') + '</button>';
  });
  if (ext.length > 4 && sid) h += '<button type="button" class="ai365-res-chip" data-ai365-resopen="' + ai365Esc(sid) + '">⋯</button>';
  return h + '</div>';
}

function ai365KxExploreBtn(kx, card) {
  const A = AI365_KX_AGENT[card.agent];
  // 로컬 전용 카드는 [탐색] 없음: 탐색은 Public 문서를 묻는 미니 채팅이라 고른 로컬과 맞지 않는다 / no [Explore] on a local-only card (explore searches Public)
  if (!A || !A.explore || card.localOnly) return '';
  return '<button type="button" class="ai365-kx-explore" data-kx-explore="' + ai365Esc(kx.sid || '') + '" data-kx-agent="' + card.agent + '"' + (kx.sid ? '' : ' disabled') + '>'
    + ai365T('탐색') + ' <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14"/><path d="m13 6 6 6-6 6"/></svg></button>';
}

/* 카드 1장 = 에이전트 헤더 + 진행 블록. 카드가 하나뿐이고 웹 카드가 없으면 공통 줄도 그 안에(시안 4 모양),
   여러 장이면 공통 줄은 카드들 아래 '취합' 블록으로 분리된다. */
/* One card = agent header + progress block. With a single card and no web card the shared lines render inside it
   (design-4 look); with several cards the shared lines become a separate aggregation block below. */
/* 병렬 타일 전용 ⊖ 줄 — 생각 그룹 줄(서술형)은 상태 아이콘 대신 스텝 아이콘으로 그린다(시안) */
/* Flat step lines for parallel tiles — descriptive group lines use the step icon, not status icons */
const AI365_KX_STEP_IC = '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><path d="M8.5 12h7"/></svg>';
function ai365KxTileLineHtml(text) {
  return '<div class="ai365-kx-line done tile">' + AI365_KX_STEP_IC + '<span>' + ai365Esc(text) + '</span></div>';
}

function ai365KxCardHtml(kx, card, withCommon) {
  const A = AI365_KX_AGENT[card.agent] || AI365_KX_AGENT.knowledge;
  if (!withCommon) {
    // 병렬 시안(2026-08-24, 디자인만): 2열 틴트 타일 — 헤더(아이콘·라벨·탐색) + 리소스 수 +
    // 굵은 작업 제목 + 평면 ⊖ 줄(생각 그룹 줄을 카드 안으로, 진행줄은 상태 아이콘 유지).
    // Parallel redesign (design only): two-column tinted tiles — header + counts + bold task title
    // + flat step lines (think-group lines move into the card; progress lines keep their icons).
    let flat = '';
    (card.groups || []).forEach(function (g) {
      (g.lines || []).forEach(function (l) { flat += ai365KxTileLineHtml(l); });
    });
    return '<div class="ai365-kx-box ai365-kx-tile" data-kx-card="' + card.agent + '">'
      + '<div class="ai365-kx-card">' + ai365KxAgentIcon(card.agent)
      + '<span class="ai365-kx-card-tx"><b>' + ai365T(A.label) + '</b><i class="ai365-kx-sub">' + ai365Esc(ai365KxSubLabel(card)) + '</i></span>'
      + ai365KxExploreBtn(kx, card) + '</div>'
      + (kx.titleDistinct && card.title ? '<div class="ai365-kx-tile-tt">' + ai365Esc(card.title) + '</div>' : '')
      + '<div class="ai365-kx-lines">' + flat + card.lines.map(ai365KxLineHtml).join('') + '</div>'
      + '</div>';
  }
  const lines = withCommon ? card.lines.concat(kx.common) : card.lines;
  return '<div class="ai365-kx-box" data-kx-card="' + card.agent + '">'
    + '<div class="ai365-kx-card">' + ai365KxAgentIcon(card.agent)
    + '<span class="ai365-kx-card-tx"><b>' + ai365T(A.label) + '</b><i class="ai365-kx-sub">' + ai365Esc(ai365KxSubLabel(card)) + '</i></span>'
    + ai365KxExploreBtn(kx, card) + '</div>'
    + '<div class="ai365-kx-prog">' + (kx.title && withCommon ? '<div class="ai365-kx-title">' + ai365Esc(kx.title) + '</div>' : '')
    + '<div class="ai365-kx-lines">' + lines.map(ai365KxLineHtml).join('') + '</div></div>'
    + '</div>';
}

function ai365KxWebHtml(kx) {
  const w = kx.web;
  if (!w) return '';
  const en = ai365KxEn();
  const sub = w.ext.length ? (en ? ('External sources ' + w.ext.length) : ('외부 출처 ' + w.ext.length + '개'))
    : (w.lines.length && w.lines.every(function (l) { return l.done; }) ? ai365T('웹 보완 불필요') : ai365T('웹 보완 확인 중'));
  return '<div class="ai365-agx-scnt ai365-kx-extcap">' + ai365T('외부 리소스') + ' ' + w.ext.length + ai365T('개') + '</div>'
    + '<div class="ai365-kx-box ai365-kx-webbox" data-kx-card="web">'
    + '<div class="ai365-kx-card">' + AI365_KX_WEB_IC
    + '<span class="ai365-kx-card-tx"><b>' + ai365T('웹 검색') + '</b><i class="ai365-kx-sub">' + ai365Esc(sub) + '</i></span></div>'
    + '<div class="ai365-kx-prog"><div class="ai365-kx-lines">' + w.lines.map(ai365KxLineHtml).join('') + '</div>'
    + ai365KxExtChips(w.ext, kx.sid) + '</div></div>';
}

/* 로컬 지식 카드(2026-09-30) — 웹 검색 카드와 같은 골격: 캡션(로컬 리소스 N개) + 카드(아이콘 · 제목 · 로컬 배지 · 요약) + 진행줄 +
   done.sources.local 의 문서 칩(누르면 로컬 미리보기). 요약 = 에이전트 · 파일 수, 없으면 진행 중 / 참조 없음.
   Local-knowledge card (2026-09-30): the web card's frame: caption (local resources N) + card (icon, title, Local badge,
   summary) + progress lines + document chips from done.sources.local (click = local preview). Summary = agents and files,
   otherwise asking / none referenced. */
function ai365KxLocalHtml(kx) {
  const L = kx.local;
  if (!L) return '';
  const en = ai365KxEn();
  const items = L.items || [];
  const files = ai365LocalFiles(items);
  const agents = new Set(items.map(function (it) { return it.agent_id || it.agent || ''; })).size;
  const sub = items.length ? (en ? ('Agents ' + agents + ' · Files ' + files) : ('에이전트 ' + agents + ' · 파일 ' + files))
    : (L.lines.length && L.lines.every(function (l) { return l.done; }) ? ai365T('참조한 로컬 문서 없음') : ai365T('로컬 에이전트에 질문 중'));
  return '<div class="ai365-agx-scnt ai365-kx-extcap ai365-kx-localcap">' + ai365T('로컬 리소스') + ' ' + files + (en ? '' : '개') + '</div>'
    + '<div class="ai365-kx-box ai365-kx-localbox" data-kx-card="local">'
    + '<div class="ai365-kx-card">' + AI365_RES_ICONS.local
    + '<span class="ai365-kx-card-tx"><b>' + ai365T('로컬 지식 에이전트') + ' ' + ai365LocalBadgeHtml() + '</b><i class="ai365-kx-sub">' + ai365Esc(sub) + '</i></span></div>'
    + '<div class="ai365-kx-prog"><div class="ai365-kx-lines">' + L.lines.map(ai365KxLineHtml).join('') + '</div>'
    + ai365LocalChipsHtml(items, kx.sid, false) + '</div></div>';
}

function ai365KxFrameHtml(kx) {
  // 웹 · 로컬 카드가 있으면 공통 줄(취합)을 카드들 아래로 따로 그린다 / with a web or local card the shared (aggregation) lines render below the cards
  // 워크플로우 세그먼트(단계 있음)는 단계 수 · 카드 수와 무관하게 타일 배치 — 카드 안에 생각 그룹 줄이 남고, 하단은 현재 단계 트리(2026-09-30)
  // Workflow segments (staged) always use the tile layout whatever the stage and card count: think-group lines stay in the cards and
  // the bottom shows the current-stage tree (2026-09-30)
  const single = kx.cards.length <= 1 && !kx.web && !kx.local && !(kx.stages && kx.stages.length);
  const en = ai365KxEn();
  let h = aiHead('', false)
    + '<div class="ai365-agx-srcrow"><button type="button" class="ai365-kx-resopen" data-kx-resopen' + (kx.sid ? ' data-ai365-resopen="' + ai365Esc(kx.sid) + '"' : '') + '>'
    + ai365T('리소스') + AI365_RES_CHEV + '</button></div>'
    + '<div class="ai365-agx-scnt">' + (en ? ('Internal resources ' + kx.cards.length) : ('사내 리소스 ' + kx.cards.length + '개')) + '</div>';
  if (single) {
    kx.cards.forEach(function (c) { h += ai365KxCardHtml(kx, c, true); });
  } else {
    // 병렬 시안(2026-08-24): 카드 2열 그리드. 카드 제목이 전부 같으면(자동 라우팅 — 파이프라인이
    // 병렬 작업에 공유 정제 질의를 준다) 상단에 1번만 쓰고 카드 안 제목은 숨긴다(중복 방지).
    // Two-column grid. Identical card titles (auto routing shares one refined query) render once
    // at the top instead of repeating inside every card.
    const distinct = new Set(kx.cards.map(function (c) { return c.title || ''; })).size > 1;
    if (!distinct && kx.title) h += '<div class="ai365-kx-title ai365-kx-title-top">' + ai365Esc(kx.title) + '</div>';
    kx.titleDistinct = distinct;
    if (kx.cards.length) h += '<div class="ai365-kx-grid">' + kx.cards.map(function (c) { return ai365KxCardHtml(kx, c, false); }).join('') + '</div>';
  }
  h += ai365KxLocalHtml(kx);   // 로컬 지식 카드(2026-09-30) — 사내 카드 다음, 웹 카드 앞(실행 순서) / local card: after internal cards, before web (run order)
  h += ai365KxWebHtml(kx);
  if (!single && kx.common.length) {
    h += '<div class="ai365-kx-common"><div class="ai365-kx-lines">' + kx.common.map(ai365KxLineHtml).join('') + '</div></div>';
  }
  // 워크플로우 세그먼트(단계 있음)는 single 이 아니므로 늘 현재 단계 트리(ai365KxStagesHtml, 2026-09-30) / staged segments are never single, so they always get the current-stage tree
  h += single ? ai365KxThinkHtml(ai365KxAllGroups(kx), !!kx.fold, kx.gfold) : ai365KxStagesHtml(kx);
  h += ai365KxBiHtml(kx);
  return h;
}

/* 병렬 하단 트리(시안, 디자인만): 생각 그룹은 카드 안으로 옮겨졌으므로 여기는 단계·작업 요약만 —
   "작업을 단계별로 실행" → "1단계 · N개 작업 병렬 실행 완료" → 작업(카드) 제목 목록.
   접힘 클래스는 기존 think 트리와 동일해 ai365KxPaint의 접힘 보존이 그대로 동작한다. */
/* Parallel bottom tree (design only): think groups moved into the cards, so this shows only the
   stage/task summary. Fold classes match the old think tree, so paint-time fold preservation holds. */
function ai365KxStagesHtml(kx) {
  if (!kx.cards.length && !(kx.stages && kx.stages.length)) return '';   // 단계 프레임은 카드가 아직 없어도 트리를 그린다 / staged frames draw the tree before any card
  const en = ai365KxEn();
  if (kx.stages && kx.stages.length) {
    // 워크플로우(2026-09-30 개편): 세그먼트 하나가 한 단계를 실행하므로 하단 트리는 "작업을 병렬로 실행" 아래 **현재 단계**의 작업만 둔다
    // (종전 "작업을 단계별로 실행" 전 단계 트리는 폐지 — 단계 진행은 컴포저 자리의 진행 표시줄이 보여 준다). 현재 단계 = 이 세그먼트의
    // running · waiting 단계(ai365KxStage 의 kx.cur), 없으면 아직 끝나지 않은 첫 단계.
    // Workflows (2026-09-30 redesign): one segment runs one stage, so the bottom tree lists only the CURRENT stage's tasks under
    // "Running tasks in parallel" (the old all-stage "run tasks by stage" tree is retired; stage progress lives in the progress
    // bar where the composer was). Current = this segment's running/waiting stage (kx.cur from ai365KxStage), else the first
    // stage not yet done.
    const cur = kx.stages.find(function (s) { return Number(s.no) === Number(kx.cur); })
      || kx.stages.find(function (s) { return s.status !== 'done'; }) || kx.stages[kx.stages.length - 1];
    return '<div class="ai365-agx-think' + (kx.fold ? ' fold' : '') + '" data-flow-tree="' + ai365Esc(String((cur && cur.no) || '')) + '">'
      + '<div class="ai365-agx-tkhd" data-agxfold="root">' + AI365_AGX_BRANCH_IC + '<span>' + ai365T('작업을 병렬로 실행') + '</span>' + AI365_AGX_CHEV_IC + '</div>'
      + '<div class="ai365-agx-tkbody">' + ((cur && cur.tasks) || []).map(function (t) { return '<div class="ai365-agx-tkline">' + AI365_AGX_ARROW_IC + '<span>' + ai365Esc(t) + '</span></div>'; }).join('')
      + '</div></div>';
  }
  const n = kx.cards.length + (kx.local ? 1 : 0) + (kx.web ? 1 : 0);
  const settled = kx.cards.every(function (c) { return c.lines.length && c.lines.every(function (l) { return l.done; }); });
  const stageLabel = en
    ? ('Stage 1 · ' + n + (n > 1 ? ' tasks run in parallel' : ' task run') + (settled ? ' — done' : ''))
    : ('1단계 · ' + n + '개 작업 ' + (n > 1 ? '병렬 ' : '') + '실행' + (settled ? ' 완료' : ' 중'));
  const rows = kx.cards.map(function (c) {
    const A = AI365_KX_AGENT[c.agent] || AI365_KX_AGENT.knowledge;
    return (kx.titleDistinct && c.title) ? c.title : ai365T(A.label);   // 공유 제목이면 에이전트 라벨로 구분 / agent labels when the title is shared
  }).concat(kx.local ? [ai365T('로컬 지식 에이전트')] : []).concat(kx.web ? [ai365T('웹 검색')] : []);
  return '<div class="ai365-agx-think' + (kx.fold ? ' fold' : '') + '">'
    + '<div class="ai365-agx-tkhd" data-agxfold="root">' + AI365_AGX_BRANCH_IC + '<span>' + ai365T('작업을 단계별로 실행') + '</span>' + AI365_AGX_CHEV_IC + '</div>'
    + '<div class="ai365-agx-tkbody">'
    + '<div class="ai365-agx-tkgrp' + (kx.gfold && kx.gfold[0] ? ' fold' : '') + '"><div class="ai365-agx-tkghd" data-agxfold>' + AI365_AGX_ARROW_IC + '<span>' + ai365Esc(stageLabel) + '</span>' + AI365_AGX_CHEV_IC + '</div>'
    + '<div class="ai365-agx-tkglines">'
    + rows.map(function (t) { return '<div class="ai365-agx-tkline">' + AI365_AGX_ARROW_IC + '<span>' + ai365Esc(t) + '</span></div>'; }).join('')
    + '</div></div></div></div>';
}

/* 프레임 재그리기 — 본문(.ai-body) 앞 영역을 통째로 교체(접힘 상태는 유지) */
/* Repaint — replaces everything before the body (.ai-body); fold state is preserved */
function ai365KxPaint(wrap, kx) {
  const th = wrap.querySelector('.ai365-agx-think');
  if (th) {
    kx.fold = th.classList.contains('fold');
    // 그룹별 접힘도 재그리기 너머로 보존(리뷰 확정) / per-group folds survive the repaint (review finding)
    kx.gfold = Array.prototype.map.call(th.querySelectorAll('.ai365-agx-tkgrp'), function (g) { return g.classList.contains('fold'); });
  }
  const body = wrap.querySelector('.ai-body');
  const html = ai365KxFrameHtml(kx);
  if (body) {
    let n = body.previousSibling;
    while (n) { const p = n.previousSibling; n.parentNode.removeChild(n); n = p; }
    body.insertAdjacentHTML('beforebegin', html);
  } else {
    wrap.innerHTML = html;
  }
}

/* ── 라이브 스트림 훅(ai365HandleEvent에서 호출) ── */
/* ── Live-stream hooks (called from ai365HandleEvent) ── */
function ai365KxInit(wrap, state, ev) {
  const t0 = ev.tasks[0];
  // 단계 프레임(2026-09-11)은 첫 단계에 카드가 없을 수 있어 제목을 task_tree.query 로도 받는다 / staged frames may start card-less: title also from task_tree.query
  const refined = ev.query || (t0 && t0.children && t0.children[0] && t0.children[0].label) || '';
  state.kx = { title: refined,
    cards: ev.tasks.map(function (t) {
      const c = ai365KxCard(t.id);
      // 병렬 시안(2026-08-24): 카드 안 굵은 작업 제목 = 그 에이전트의 세부 작업 라벨
      // Parallel redesign: the bold in-card title = that agent's refined task label
      c.title = (t.children && t.children[0] && t.children[0].label) || t.label || '';
      return c;
    }), web: null, common: [],
    // 워크플로우 단계(2026-09-09): 서버가 task_tree.stages 로 실제 단계·작업을 주면 하단 트리를 그 단계로 그린다
    // Workflow stages (2026-09-09): when the server sends task_tree.stages, the bottom tree shows those real stages
    stages: (ev.stages || []).map(function (s) { return { no: s.no, tasks: s.tasks || [], status: 'pending' }; }),
    sid: null, fold: false, bi: [], ext: [] };
  if (state.kx.stages.length) state.kx.cards.forEach(function (c) { c.gated = true; });   // 단계 프레임 표식 / gated-frame marker
  wrap.classList.add('ai365-kx');
  wrap.innerHTML = ai365KxFrameHtml(state.kx);
}

/* 에이전트 상태는 자기 카드 줄만 건드린다(병렬 중 다른 카드의 대기 줄은 그대로). task_id가 없으면(중단·오류) 전체 마감. */
/* Agent status touches only its own card (other cards keep their pending lines in parallel). No task_id (stop/error) settles all. */
function ai365KxStatus(state, ev) {
  const kx = state.kx;
  const card = kx.cards.find(function (c) { return c.agent === ev.task_id; }) || null;
  if (!card) {
    ai365KxAllLists(kx).forEach(function (ls) { ls.forEach(function (l) { l.done = true; }); });
    if (ev.status === 'failed' || ev.status === 'done') kx.common.push({ text: ev.detail || ai365T('(실패)'), done: true, raw: true, fail: ev.status === 'failed' });
    return;
  }
  const A = AI365_KX_AGENT[card.agent] || AI365_KX_AGENT.knowledge;
  card.started = true;   // 단계 게이트(2026-09-11): 시작한 카드만 마감 시 과거형으로 정리한다(뒷 단계 카드는 계획 문구 유지) / only started cards settle to past tense at done
  // 서버 표식 local_only(2026-10-28): 로컬 전용 자리라 Public 검색 문구 · 생각 그룹을 지우고 서버 사유 줄만 남긴다(복원도 같은 길)
  // The server's local_only flag: a local-only slot, so the Public search copy and think groups go and only server lines stay (restore too)
  if (ev.local_only && card.agent === 'knowledge' && !card.localOnly) {
    card.localOnly = true;
    card.groups = [];
    card.lines = card.lines.filter(function (l) { return l.raw; });
  }
  if (ev.status === 'running') {
    if (!card.localOnly) ai365KxPush(card.lines, A.running, false);
  } else if (ev.status === 'done') {
    card.lines.forEach(function (l) { l.done = true; });
    if (ev.detail) ai365KxPush(card.lines, ev.detail, true, { raw: true });
  } else if (ev.status === 'failed') {
    card.lines.forEach(function (l) { l.done = true; });
    ai365KxPush(card.lines, ev.detail || ai365T('(실패)'), true, { raw: true, fail: true });
  }
}

/* 워크플로우 단계 진행(2026-09-09): stage_status running/done → 하단 트리 라벨 / workflow stage progress → bottom-tree labels */
function ai365KxStage(state, ev) {
  const kx = state.kx;
  const st = (kx.stages || []).find(function (x) { return String(x.no) === String(ev.stage); });
  if (st) st.status = ev.status || st.status;
  // 이 세그먼트가 실행하는 현재 단계(재생된 done 은 제외, 2026-09-30) — 하단 트리가 그 단계의 작업만 보여 준다
  // The current stage this segment runs (replayed done excluded, 2026-09-30); the bottom tree lists only its tasks
  if (ev.status === 'running' || ev.status === 'waiting') kx.cur = Number(ev.stage) || kx.cur;
  // 단계 시작 이벤트가 그 단계의 카드를 실어 온다(2026-09-11) — 앞 단계 카드와 나란히 뒤에 붙는다
  // The stage-start event carries that stage's cards (2026-09-11) — appended after the earlier stages' cards
  if (ev.cards && ev.cards.length) ai365KxAddCards(kx, ev.cards, kx.title, !!kx.isStatic);
}

function ai365KxAnswerHead(wrap, state) {
  const kx = state.kx;
  const last = kx.common[kx.common.length - 1];
  if (!last || last.done) ai365KxLine(state, '답변을 작성하고 있습니다', false);
  ai365KxPaint(wrap, kx);
  wrap.insertAdjacentHTML('beforeend', '<div class="ai-body"><div class="think-row ai365-gen"><span class="spinner"></span>' + ai365T('답변을 생성 중입니다') + '</div></div>');
  state.body = wrap.querySelector('.ai-body:last-of-type') || wrap.querySelector('.ai-body');
}

/* 대시보드 카드는 본문 표가 아니라 프레임의 BI 임베드 카드로(시안 6) — 나머지 카드(표)는 본문에 그대로 */
/* Dashboard cards become the frame's BI embed card (design 6); other cards (tables) stay in the body */
function ai365KxSplitCards(cards, kx) {
  const rest = [];
  (cards || []).forEach(function (c) {
    if (c && c.kind === 'dashboard') {
      // 카드 제목은 파일 스템("경영Dashboard")이라 워크스페이스 슬롯 라벨("월간 손익 대시보드")로 바꿔 단다(시안 6)
      // The card title is the file stem; prefer the workspace slot label (design 6)
      let file = '';
      try { file = decodeURIComponent(String(c.thumb_url || '').split('/').pop() || ''); } catch (e) { file = ''; }
      const label = file ? ai365FlpBiLabel(file) : '';
      kx.bi.push({ title: (label && label !== file) ? label : (c.title || 'BI'), url: c.thumb_url || '' });
    } else rest.push(c);
  });
  return rest;
}

function ai365KxBiHtml(kx) {
  return (kx.bi || []).map(function (b) { return ai365BiEmbHtml(b.title, b.url); }).join('');
}

function ai365KxDone(wrap, state, ev) {
  const kx = state.kx;
  ai365KxAllLists(kx).forEach(function (ls) { ls.forEach(function (l) { l.done = true; }); });
  if (ev.sources) ai365KxApplySources(kx, ev.sources); else kx.cards.forEach(ai365KxSettleGroups);
  // 탐색 앵커 = 이 답변의 message id — 탐색 하나하나가 자기 히스토리를 갖는 키(사용자 요청 2차)
  // Exploration anchor = this answer's message id — the key that gives each exploration its own history
  if (ev.message_id) {
    kx.mid = String(ev.message_id);
    if (kx.sid && AI365_KX_DOCS[kx.sid]) AI365_KX_DOCS[kx.sid].mid = kx.mid;
  }
  ai365KxPaint(wrap, kx);
}

/* sources에 이 에이전트가 없을 때(무결과·실패·중단) 계획 그룹을 과거형으로 마감 — 완료된 프레임이 계획처럼 읽히지 않게(리뷰 확정) */
/* Settle plan groups to past tense when done.sources has no entry for this agent (no result / failure / stop) */
function ai365KxSettleGroups(card) {
  // 단계 게이트 프레임(2026-09-11): 아직 시작하지 않은 뒷 단계 카드는 계획 문구(현재형)를 유지한다 / gated frames keep not-yet-started cards in plan tense
  if (card.gated && !card.started) return;
  const en = ai365KxEn();
  const past = function (x) {
    x = String(x || '');
    if (en) return x.replace(/^Checking /, 'Checked ').replace(/^Searching /, 'Searched ').replace(/^Querying /, 'Queried ').replace(/^Analyzing /, 'Analyzed ').replace(/^Running /, 'Ran ').replace(/^Preparing /, 'Prepared ').replace(/^Extracting /, 'Extracted ');
    return x.replace(/합니다\.?$/, '했습니다.');
  };
  const g = (card.groups || []).slice(0, -1).map(function (x) { return { label: past(x.label), lines: (x.lines || []).map(past) }; });
  if (card.lines.some(function (l) { return l.fail; })) g.push({ label: ai365T('관련 결과를 찾지 못했습니다.'), lines: [] });
  g.push(ai365KxFinalGroup(card.agent === 'data' ? 'data' : (card.agent === 'api' ? 'api' : 'knowledge'), true));
  card.groups = g;
}

/* done.sources → 카드별 확정(수치·그룹), 탐색 레지스트리, 외부 출처는 웹 카드로, 로컬 출처(2026-09-30)는 로컬 카드 칩으로 */
/* done.sources → settle each card (counts, groups), the explore registry, external sources into the web card and local
   sources (2026-09-30) into the local card chips */
function ai365KxApplySources(kx, sources) {
  if (!sources) return;
  const k = sources.knowledge, d = sources.data, w = sources.work, gw = sources.groupware, ext = sources.external || [];
  const lItems = (sources.local && sources.local.items) || [];   // 로컬 지식(2026-09-30) / local knowledge
  if (k || d || w || gw || ext.length || lItems.length) kx.sid = kx.sid || ai365SrcRegister(sources);
  if (lItems.length) {   // 로컬 카드의 문서 칩(진행줄이 없던 복원도 카드를 세운다) / local card chips (a restore without lines still gets the card)
    if (!kx.local) kx.local = { lines: [], items: [] };
    kx.local.items = lItems.slice();
  }
  if (kx.sid) AI365_KX_DOCS[kx.sid] = { knowledge: (k && k.items) ? k.items.slice() : [],
    data: (d && d.items) ? d.items.slice() : [], groupware: (gw && gw.items) ? gw.items.slice() : [] };
  kx.cards.forEach(function (c) {
    if (c.agent === 'knowledge' && k) {
      // 파일 수는 청크가 아니라 **인용된 문서(제목 중복 제거)** 기준 / distinct cited documents, not chunks
      c.folders = k.folders || 0;
      c.files = ai365KxDocList('knowledge', k.items || []).length || k.files || 0;
    } else if (c.agent === 'data' && d) {
      c.resources = ai365KxDocList('data', d.items || []).length || d.resources || 0;
    } else if (c.agent === 'groupware' && gw) {
      c.resources = (gw.items || []).length || gw.resources || 0;
    }
    if (c.localOnly) { c.groups = []; return; }   // 로컬 전용 카드는 Public 출처 그룹을 만들지 않는다 / no Public source groups on a local-only card
    const g = ai365KxGroupsFromSources(c.agent, sources);
    if (g) c.groups = g; else ai365KxSettleGroups(c);
  });
  kx.ext = ext;
  if (ext.length) {
    if (!kx.web) kx.web = { lines: [], ext: [] };
    kx.web.ext = ext;
  }
}

/* 새로고침 복원 — 서버가 덧붙인 meta.trace(이벤트 순서)를 라이브와 같은 함수로 재생 */
/* Refresh restore — replays the server-attached meta.trace (event order) through the live functions */
function ai365KxStaticEl(message) {
  const meta = message.meta || {};
  const tr = meta.trace || {};
  const tasks = (tr.tasks || []).filter(function (t) { return t && AI365_KX_AGENT[t.id]; });
  const t0 = tasks[0] || {};
  // isStatic: 단계 시작 라인(stage.cards)으로 붙는 카드도 복원 모양으로 만든다(2026-09-11) / cards attached by stage lines use the restore shape
  const c00 = (t0.children || [])[0];   // 문자열 또는 {id, label}(서버 트레이스) / a string or {id, label} (server trace)
  const state = { kx: { title: tr.query || ((c00 && typeof c00 === 'object') ? (c00.label || '') : (c00 || '')), cards: [], web: null, common: [], sid: null, fold: false, bi: [], ext: [], isStatic: true } };
  // 복원은 체크 범위를 모르므로 범위 기반 수치 없이 시작 → sources로 확정 / restore has no scope; counts come from sources
  state.kx.cards = tasks.map(function (t) {
    return { agent: t.id, lines: [], folders: 0, files: 0, resources: t.id === 'work' ? 1 : 0,
      // 카드 제목 — 라이브(ai365KxInit)와 동일 계약, 서버 트레이스의 {id, label} 객체면 라벨만(2026-09-30) / same contract as live; {id, label} objects give their label
      title: (function (c0) { return (c0 && typeof c0 === 'object') ? (c0.label || '') : (c0 || ''); })((t.children || [])[0]) || t.label || '',
      groups: ai365KxGroupsFromNames(t.id, []) };
  });
  // 워크플로우 단계 복원(2026-09-09) — trace.stages + 'stage' 라인 / workflow stage restore — trace.stages + 'stage' lines
  state.kx.stages = (tr.stages || []).map(function (x) { return { no: x.no, tasks: x.tasks || [], status: 'pending' }; });
  if (state.kx.stages.length) state.kx.cards.forEach(function (c) { c.gated = true; });   // 단계 프레임 표식 / gated-frame marker
  const seq = tr.lines && tr.lines.length
    ? tr.lines
    : (tr.thinking || []).map(function (x) { return { t: 'thinking', text: x }; });
  seq.forEach(function (l) {
    if (l.t === 'thinking') ai365KxLine(state, l.text, false);
    else if (l.t === 'status') ai365KxStatus(state, { task_id: l.task_id, status: l.status, detail: l.detail, local_only: l.local_only });
    else if (l.t === 'stage') ai365KxStage(state, { stage: l.stage, status: l.status, cards: l.cards });
  });
  ai365KxAllLists(state.kx).forEach(function (ls) { ls.forEach(function (x) { x.done = true; }); });
  if (meta.sources) ai365KxApplySources(state.kx, meta.sources);
  if (message.id) {   // 탐색 앵커(위 ai365KxDone과 동일 계약) / exploration anchor (same contract as live)
    state.kx.mid = String(message.id);
    if (state.kx.sid && AI365_KX_DOCS[state.kx.sid]) AI365_KX_DOCS[state.kx.sid].mid = state.kx.mid;
  }
  const cards = ai365KxSplitCards(meta.cards, state.kx);
  // 복원은 접힌 트리로(시안 5의 완료 상태) / restored trees start folded (the settled state of design 5)
  state.kx.fold = true;
  const wrap = document.createElement('div');
  wrap.className = 'msg msg-ai ai365-kx';
  wrap.setAttribute('data-saveable', '');
  const sources = meta.sources || null;
  // OpenUI 답(2026-10-27)은 섬 자리만(각주 렌더 없음), 옵저버가 올린다 / an OpenUI answer gets the island slot only (no footnotes); the observer mounts it
  const oui = meta.format === 'openui' && typeof ai365OuiPlaceholderHtml === 'function';
  const hasFn = !oui && !!(sources && sources.supports && sources.supports.length);
  const body = oui ? ai365OuiPlaceholderHtml(message) : (hasFn ? ai365CiteMd(String(message.content), sources) : ai365MnMd(String(message.content)));
  wrap.innerHTML = ai365KxFrameHtml(state.kx)
    + '<div class="ai-body"' + (hasFn && state.kx.sid ? ' data-ai365-csid="' + ai365Esc(state.kx.sid) + '"' : '') + '>' + body + ai365CardsHtml(cards) + '</div>'
    + FOOT;
  if (typeof ai365WgInsert === 'function') ai365WgInsert(wrap.querySelector('.ai-body'), meta.cards);   // 실시간 위젯 / live widgets
  return wrap;
}

/* ── 데이터 탐색기(시안 2·4): Select Source | Preview Data · Schema Table — 런처 미리보기와 탐색 패널이 공용 ── */
/* ── Data explorer (designs 2·4): Select Source | Preview Data · Schema Table — shared by the launcher preview and the explore panel ── */
const AI365_DX = {};   // id → { tables:[{table,label,kind}], cur, tab, cache:{table:data}, loading:{} }
const AI365_DX_ROWS = 20;

function ai365DxState(id, tables, cur) {
  const st = AI365_DX[id] || (AI365_DX[id] = { tables: [], cur: null, tab: 'preview', cache: {}, loading: {} });
  st.tables = tables || [];
  if (cur && st.tables.some(function (t) { return t.table === cur; })) st.cur = cur;
  else if (!st.cur || !st.tables.some(function (t) { return t.table === st.cur; })) st.cur = st.tables.length ? st.tables[0].table : null;
  return st;
}

function ai365DxHtml(id) {
  const st = AI365_DX[id];
  if (!st || !st.tables.length) return '';
  const cur = st.tables.find(function (t) { return t.table === st.cur; }) || st.tables[0];
  const d = st.cache[cur.table];
  let body;
  if (!d) {
    body = '<div class="think-row"><span class="spinner"></span>' + ai365T('미리보기를 불러오는 중입니다') + '</div>';
  } else if (d.error) {
    body = '<div class="ai365-fl-none">' + ai365T('미리보기를 불러오지 못했습니다') + '</div>';
  } else if (st.tab === 'schema') {
    body = '<div class="ai365-dx-tt">' + ai365T('Schema of') + ' ' + ai365Esc(d.label || cur.label) + '</div>'
      + '<div class="ai365-dx-tblwrap"><table class="pos-table"><tr><th>#</th><th>Column</th><th>Type</th></tr>'
      + (d.schema || []).map(function (c, i) { return '<tr><td>' + (i + 1) + '</td><td>' + ai365Esc(c.name) + '</td><td>' + ai365Esc(c.type || '') + '</td></tr>'; }).join('')
      + '</table></div>';
  } else {
    body = '<div class="ai365-dx-tt">' + ai365T('Dataset Preview of') + ' ' + ai365Esc(d.label || cur.label) + '</div>'
      + '<div class="ai365-dx-tblwrap"><table class="pos-table"><tr>' + (d.columns || []).map(function (c) { return '<th>' + ai365Esc(c) + '</th>'; }).join('') + '</tr>'
      + (d.rows || []).slice(0, AI365_DX_ROWS).map(function (r) { return '<tr>' + r.map(function (v) { return '<td>' + ai365Esc(ai365FormatCell(v)) + '</td>'; }).join('') + '</tr>'; }).join('')
      + '</table></div>';
  }
  return '<div class="ai365-dx" data-dx="' + ai365Esc(id) + '">'
    + '<div class="ai365-dx-src"><div class="ai365-dx-src-hd">Select Source</div>'
    + st.tables.map(function (t) {
      return '<button type="button" class="ai365-dx-srcbtn' + (t.table === cur.table ? ' on' : '') + '" data-dx-src="' + ai365Esc(t.table) + '" title="' + ai365Esc(t.table) + '">' + ai365Esc(t.label || t.table) + '</button>';
    }).join('') + '</div>'
    + '<div class="ai365-dx-main"><div class="ai365-dx-tabs">'
    + '<button type="button" class="ai365-dx-tab' + (st.tab !== 'schema' ? ' on' : '') + '" data-dx-tab="preview">Preview Data</button>'
    + '<button type="button" class="ai365-dx-tab' + (st.tab === 'schema' ? ' on' : '') + '" data-dx-tab="schema">Schema Table</button></div>'
    + '<div class="ai365-dx-body">' + body + '</div></div></div>';
}

function ai365DxRender(id) {
  const st = AI365_DX[id];
  const el = document.querySelector('[data-dx="' + id + '"]');
  if (!st || !el) return;
  el.outerHTML = ai365DxHtml(id);
  ai365DxEnsure(id);
}

function ai365DxEnsure(id) {
  const st = AI365_DX[id];
  if (!st || !st.cur || st.cache[st.cur] || st.loading[st.cur]) return;
  const t = st.cur;
  st.loading[t] = true;
  fetch('/api/resources/data/preview?table=' + encodeURIComponent(t) + '&limit=' + AI365_DX_ROWS + '&acting_user_id=' + encodeURIComponent(ai365ActingId()))
    .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(function (d) { st.cache[t] = d; })
    .catch(function () { st.cache[t] = { error: true }; })
    .then(function () { delete st.loading[t]; if (st.cur === t) ai365DxRender(id); });
}

document.addEventListener('click', function (e) {
  const src = e.target.closest('[data-dx-src]');
  const tab = e.target.closest('[data-dx-tab]');
  if (!src && !tab) return;
  const box = e.target.closest('[data-dx]');
  if (!box) return;
  const id = box.getAttribute('data-dx'), st = AI365_DX[id];
  if (!st) return;
  if (src) st.cur = src.getAttribute('data-dx-src');
  if (tab) st.tab = tab.getAttribute('data-dx-tab');
  ai365DxRender(id);
});

/* ── BI 임베드 카드(시안 5·6) + 확대 모달(시안 8) — 업무자동화 임베드 카드와 같은 골격, 본문은 이미지 ── */
/* ── BI embed card (designs 5·6) + expand modal (design 8) — same skeleton as the Automation embed card, image body ── */
function ai365BiEmbHtml(title, url, opts) {
  // opts.gotoFile(선택, 런처 미리보기 전용): [|→] 버튼이 접기 대신 **리소스 센터 BI 갤러리로 이동**
  // (2026-08-31 사용자 지시 — "해당 BI가 있는 곳으로"). 채팅 kx 카드는 종전 접기 유지.
  // Optional opts.gotoFile (launcher preview only): the [|→] button navigates to the Resource Center
  // BI gallery instead of folding (user request — "go to where that BI lives"). Chat kx cards keep fold.
  const u = url.indexOf('/') === 0 ? encodeURI(url) : url;
  const second = (opts && opts.gotoFile)
    ? '<button type="button" class="ai365-agemb-btn" data-bi-goto="' + ai365Esc(opts.gotoFile) + '" title="' + ai365T('리소스 센터에서 보기') + '">' + AI365_AGEMB_FOLD_IC + '</button>'
    : '<button type="button" class="ai365-agemb-btn" data-agemb-fold title="' + ai365T('접기') + '">' + AI365_AGEMB_FOLD_IC + '</button>';
  return '<div class="ai365-agemb ai365-bi" data-bi-title="' + ai365Esc(title) + '" data-bi-url="' + ai365Esc(url) + '">'
    + '<div class="ai365-agemb-hd"><b>' + ai365Esc(title) + ' (BI)</b>'
    + '<button type="button" class="ai365-agemb-btn" data-bi-expand title="' + ai365T('크게 보기') + '">' + AI365_AGEMB_EXPAND_IC + '</button>'
    + second + '</div>'
    + '<div class="ai365-agemb-bd"><img src="' + u + '" alt="' + ai365Esc(title) + '"></div></div>';
}

function ai365BiExpand(title, url) {
  ai365AgembModalClose();
  const u = url.indexOf('/') === 0 ? encodeURI(url) : url;
  const ov = document.createElement('div');
  ov.id = 'ai365AgembModal';
  ov.className = 'ai365-agemb-ov';
  ov.innerHTML = '<div class="ai365-agemb-sheet">'
    + '<div class="ai365-agemb-hd"><b>' + ai365Esc(title) + ' (BI)</b>'
    + '<button type="button" class="ai365-agemb-btn" data-agemb-restore title="' + ai365T('접기') + '">' + AI365_AGEMB_RESTORE_IC + '</button>'
    + '<button type="button" class="ai365-agemb-btn" data-agemb-restore>' + AI365_AGEMB_FOLD_IC + '</button>'
    + '<button type="button" class="ai365-agemb-btn" data-agemb-restore>✕</button></div>'
    + '<div class="ai365-bi-full"><img src="' + u + '" alt="' + ai365Esc(title) + '"></div></div>';
  document.body.appendChild(ov);
}

document.addEventListener('click', function (e) {
  const b = e.target.closest('[data-bi-expand]');
  if (!b) return;
  const card = b.closest('.ai365-bi');
  if (card) ai365BiExpand(card.getAttribute('data-bi-title') || 'BI', card.getAttribute('data-bi-url') || '');
});

// 런처 BI 카드 [|→] — 리소스 센터 BI 갤러리로 이동(목업 훅 AI365_openBiDash, 해당 대시보드 선택 상태)
// Launcher BI card [|→] — jump to the Resource Center BI gallery (mockup hook, dashboard preselected)
document.addEventListener('click', function (e) {
  const g = e.target.closest('[data-bi-goto]');
  if (!g) return;
  if (typeof window.AI365_openBiDash === 'function') window.AI365_openBiDash(g.getAttribute('data-bi-goto'));
});

/* ── 데이터 런처 미리보기(시안 2·5) — "데이터 미리보기 N" 항목 목록(타입 배지) + 탐색기 또는 BI 카드 ── */
/* ── Data launcher preview (designs 2·5) — "Data preview N" item list (type badges) + explorer or BI card ── */
let AI365_FLP_DPREV_FOLD = false;
let AI365_FLP_LAST_BI = null;   // 직전 렌더의 BI ident 목록 — "새로 체크된 BI"만 자동으로 열기 위한 비교값(다중 선택 대응)
// the previous render's BI ident list — used to auto-open only freshly checked BIs (multi-select aware)
let AI365_FLP_BI_SEED = false;  // 런처 진입 직후 1회 — 프리셋의 BI를 "신규"로 오인해 카드를 자동으로 열지 않게 시드
// one-shot after launcher entry — seeds LAST_BI so preset BIs are not mistaken for fresh checks
function ai365DataPrevItems(scope) {
  const items = [];
  (scope.data_tables || []).forEach(function (t) { const m = ai365FlpTableMeta(t); items.push({ key: 't:' + t, kind: m.kind || 'DB', label: m.label, ident: t }); });
  (scope.data_bi || []).forEach(function (f) { items.push({ key: 'b:' + f, kind: 'BI', label: ai365FlpBiLabel(f), ident: f }); });
  return items;
}

function ai365DataPrevRender(el, scope) {
  const items = ai365DataPrevItems(scope);
  if (!items.length) { el.innerHTML = ''; el.removeAttribute('data-sig'); AI365_FLP_PREV_OPENKEY = null; AI365_FLP_LAST_BI = null; AI365_FLP_DPREV_FOLD = false; return; }
  // 자동 열림 폐지(2026-08-31 사용자 지시 — 지식 미리보기처럼 목록만): 표/CSV 탐색기는 항목을
  // 클릭해야 아래에 뜬다. 예외는 BI — **새로 체크된 순간**만 그 카드를 자동으로 연다. BI 다중 선택
  // 전환에 맞춰 직전 BI ident 목록과 비교해 신규분만 감지(재클릭으로 닫은 카드를 되살리지 않음).
  // No auto-open (user request — list-only, like the knowledge preview): the table/CSV explorer only
  // renders after an explicit click. Exception: a freshly CHECKED BI auto-opens its card once —
  // detected by diffing against the previous BI ident list (multi-select aware), so a re-click close
  // is not undone by the next render.
  if (AI365_FLP_PREV_OPENKEY && !items.some(function (x) { return x.key === AI365_FLP_PREV_OPENKEY; })) AI365_FLP_PREV_OPENKEY = null;
  const biIdents = items.filter(function (x) { return x.kind === 'BI'; }).map(function (x) { return x.ident; });
  if (AI365_FLP_BI_SEED) { AI365_FLP_BI_SEED = false; AI365_FLP_LAST_BI = biIdents.slice(); }
  const prevBi = AI365_FLP_LAST_BI || [];
  const freshBi = biIdents.filter(function (id) { return prevBi.indexOf(id) < 0; });
  if (freshBi.length) {
    const f = items.find(function (x) { return x.kind === 'BI' && x.ident === freshBi[freshBi.length - 1]; });
    if (f) AI365_FLP_PREV_OPENKEY = f.key;
  }
  AI365_FLP_LAST_BI = biIdents;
  const cur = AI365_FLP_PREV_OPENKEY ? items.find(function (x) { return x.key === AI365_FLP_PREV_OPENKEY; }) : null;
  const sig = items.map(function (x) { return x.key; }).join('|') + '#' + (cur ? cur.key : '') + '::' + (AI365_FLP_DPREV_FOLD ? 1 : 0);
  if (el.getAttribute('data-sig') === sig) { if (cur && cur.kind !== 'BI') ai365DxEnsure('prev'); return; }
  el.setAttribute('data-sig', sig);
  const rows = items.map(function (x) {
    return '<button type="button" class="ai365-kpl-file ai365-dpl-item' + (cur && x.key === cur.key ? ' on' : '') + '" data-dprev="' + ai365Esc(x.key) + '">'
      + ai365KxTypeBadge(x.kind) + '<span>' + ai365Esc(x.label + (x.kind === 'CSV' ? '.csv' : '')) + '</span></button>';
  }).join('');
  let below = '';
  if (cur && cur.kind === 'BI') {
    // gotoFile: 런처 미리보기의 [|→]는 접기 대신 리소스 센터 이동(2026-08-31)
    // gotoFile: in the launcher preview the [|→] navigates to the Resource Center instead of folding
    below = ai365BiEmbHtml(cur.label, '/static/bi_thumbs/' + cur.ident, { gotoFile: cur.ident });
  } else if (cur) {
    const tables = items.filter(function (x) { return x.kind !== 'BI'; }).map(function (x) { return { table: x.ident, label: x.label, kind: x.kind }; });
    ai365DxState('prev', tables, cur.ident);
    AI365_DX.prev.cur = cur.ident;
    below = ai365DxHtml('prev');
  }
  el.innerHTML = '<div class="ai365-flprev-card ai365-kpl' + (AI365_FLP_DPREV_FOLD ? '' : ' open') + '">'
    + '<div class="ai365-flprev-hd" data-dpfold><b>' + ai365T('데이터 미리보기') + '</b><span class="ai365-flprev-badge">' + items.length + '</span>'
    + '<span class="ai365-flprev-caret ai365-kpl-caret">' + AI365_FLP_PREV_CARET + '</span></div>'
    + '<div class="ai365-flprev-kbody"' + (AI365_FLP_DPREV_FOLD ? ' style="display:none"' : '') + '><div class="ai365-kpl-list">' + rows + '</div></div></div>'
    + (below ? '<div class="ai365-dprev-below">' + below + '</div>' : '');
  if (cur && cur.kind !== 'BI') ai365DxEnsure('prev');
}

chatInner.addEventListener('click', function (e) {
  const fold = e.target.closest('[data-dpfold]');
  if (fold) {
    AI365_FLP_DPREV_FOLD = !AI365_FLP_DPREV_FOLD;
    const card = fold.closest('.ai365-flprev-card');
    const kb = card && card.querySelector('.ai365-flprev-kbody');
    if (card) card.classList.toggle('open', !AI365_FLP_DPREV_FOLD);
    if (kb) kb.style.display = AI365_FLP_DPREV_FOLD ? 'none' : '';
    const box = document.getElementById('ai365FlpPrev');
    if (box && box.getAttribute('data-sig')) box.setAttribute('data-sig', box.getAttribute('data-sig').replace(/::[01]$/, '::' + (AI365_FLP_DPREV_FOLD ? 1 : 0)));
    return;
  }
  const it = e.target.closest('[data-dprev]');
  if (!it) return;
  // 재클릭 = 닫기(지식 미리보기와 동일 UX, 2026-08-31) / re-click closes, matching the knowledge preview
  const dk = it.getAttribute('data-dprev');
  AI365_FLP_PREV_OPENKEY = (AI365_FLP_PREV_OPENKEY === dk) ? null : dk;
  ai365FlpPrevSync('data');
});

/* ── [탐색 →] 패널 ── */
/* ── The [Explore →] panel ── */
function ai365KxDocList(agent, items) {
  const out = [];
  (items || []).forEach(function (it) {
    if (!it || !it.title) return;
    if (out.some(function (d) { return d.title === it.title; })) return;
    if (agent === 'groupware') {
      out.push({ title: it.title, kind: 'gw', key: it.key || '', ns: it.ns || '', path: it.path || [] });
    } else if (agent === 'data') {
      const lbl = (it.kind === 'bi' && it.file) ? ai365FlpBiLabel(it.file) : '';   // BI=슬롯 라벨 우선 / BI prefers the slot label
      out.push({ title: (lbl && lbl !== it.file) ? lbl : it.title, kind: it.kind === 'bi' ? 'bi' : 'table', typeKind: ai365KxItemKind(it),
        table: it.table || '', file: it.file || '', path: it.path || [] });
    } else {
      out.push({ title: it.title, page: it.page, path: it.path || [] });
    }
  });
  return out;
}

/* 패널 안에서 흐르던 미니 채팅 스트림을 끊는다 — 패널이 닫히거나 본문이 교체될 때(리뷰 확정: 숨은 스트림이
   STOP 아이콘·큐를 붙잡고 문답을 잃었다) */
/* Abort a mini-chat stream that lives inside the panel — on close or body replacement (review finding:
   a hidden stream kept the STOP icon/queue and lost the Q&A) */
function ai365KxAbortPanelStream() {
  const b = document.getElementById('artifactBody');
  // 패널 정리용 abort — 서버 실행은 계속(2026-09-03: 명시적 STOP 만 서버 중단) / UI-only abort — the server run continues (explicit STOP only)
  if (typeof ai365StreamWrap !== 'undefined' && ai365StreamWrap && b && b.contains(ai365StreamWrap)) ai365StopStream({ server: false });
}

/* ── 탐색 히스토리(2026-08-24, 사용자 요청 2차): 문답을 **탐색 하나하나** — 즉 [탐색]이 달린 앵커 답변
   메시지(× 에이전트) — 에 종속시킨다. 같은 채팅이라도 답변 A의 탐색과 답변 B의 탐색은 서로 다른
   히스토리("이전 탐색까지 쭉 이어지는" 통합 스레드 폐지). 저장소는 기존 explore 행 그대로 + anchor
   (앵커 답변 message id) 태그. 채팅 복원 루프가 숨긴 행에서 쌍을 모으고, 라이브는 onEnd에서 쌓는다. */
/* Explore history (user request, round 2): Q&A binds to EACH exploration — the anchor answer message the
   [Explore] button belongs to (× agent). Explorations of answer A and answer B keep separate histories
   (the merged per-agent thread is retired). Storage stays the explore rows + an anchor tag (the anchor
   answer's message id). The chat-restore loop collects pairs; live sends append via onEnd. */
const AI365_KX_HIST = {};   // chatId → {map:{'<anchorMid>|<agent>':[{q,a}]}, pend:{q,agent,anchor}|null}
function ai365KxHistBucket(chatId) {
  return AI365_KX_HIST[chatId] || (AI365_KX_HIST[chatId] = { map: {}, pend: null });
}
function ai365KxHistReset(chatId) { AI365_KX_HIST[chatId] = { map: {}, pend: null }; }
function ai365KxHistUser(chatId, m) {
  ai365KxHistBucket(chatId).pend = { q: String(m.content || ''), agent: (m.meta && m.meta.agent) || '',
    anchor: (m.meta && m.meta.anchor) || '' };
}
function ai365KxHistAnswer(chatId, m) {
  const h = AI365_KX_HIST[chatId];
  if (!h || !h.pend) return;
  // 답변 행 태그 우선(질문 행 폴백). 에이전트나 앵커가 없는 구버전 행은 귀속 불가 — 제외(리뷰 확정 확장).
  // Answer-row tags first (question-row fallback). Legacy rows without agent or anchor can't be attributed — excluded.
  const tag = (m.meta && m.meta.agent) || h.pend.agent;
  const anchor = (m.meta && m.meta.anchor) || h.pend.anchor;
  const pend = h.pend;
  h.pend = null;
  if ((tag !== 'knowledge' && tag !== 'data') || !anchor) return;
  const key = anchor + '|' + tag;
  (h.map[key] || (h.map[key] = [])).push({ q: pend.q, a: String(m.content || '') });
}
function ai365KxHistList(chatId, mid, agent) {
  const h = chatId && mid && AI365_KX_HIST[chatId];
  const ls = h && h.map[mid + '|' + ((agent === 'data' || agent === 'groupware') ? agent : 'knowledge')];
  return ls ? ls.slice() : [];
}
function ai365KxHistPush(chatId, mid, agent, pair) {
  if (!chatId || !mid || !pair.a) return;   // 무답변(오류·중단)은 히스토리에 남기지 않는다 / unanswered pairs are not kept
  const map = ai365KxHistBucket(chatId).map;
  const key = mid + '|' + ((agent === 'data' || agent === 'groupware') ? agent : 'knowledge');
  (map[key] || (map[key] = [])).push(pair);
}

function ai365KxExploreOpen(agent, docs, qa, chatId, anchorMid) {
  const A = AI365_KX_AGENT[agent] || AI365_KX_AGENT.knowledge;
  if (!docs || !docs.length) { if (typeof toast === 'function') toast(ai365T(agent === 'data' ? '참조된 데이터가 없습니다.' : agent === 'groupware' ? '참조된 자료가 없습니다.' : '참조된 문서가 없습니다.')); return; }
  ai365KxAbortPanelStream();
  // dirty=이 패널 세션에서 새 문답(done 도달)이 생겼는지 — 닫힐 때 "탐색 대화가 추가되었습니다" 토스트 조건
  // dirty = whether this panel session produced new (done) Q&A — gates the "exploration added" toast on close
  const st = { agent: agent, chatId: chatId || currentChatId, anchor: String(anchorMid || ''), docs: docs, cur: docs[0].title, qa: (qa || []).slice(), vh: 300, dirty: false };
  AI365_KX_EXPLORE = st;
  $('#artifactTitle').textContent = ai365T(A.label);
  artifactPanel.classList.remove('ai365-res-narrow');
  artifactPanel.classList.add('ai365-explore');
  const cnt = (agent === 'data' || agent === 'groupware')
    ? (ai365KxEn() ? ('Resources ' + docs.length) : ('리소스 ' + docs.length))
    : (ai365KxEn() ? ('Files ' + docs.length) : ('파일 ' + docs.length));
  $('#artifactBody').innerHTML = '<div class="ai365-kx-ph"><span class="ic">' + ai365KxAgentIcon(agent) + '</span>'
    + '<span><b>' + ai365T(A.label) + '</b><i>' + ai365Esc(cnt) + '</i></span>'
    // ✕ 대신 [이어가기](시안 2026-08-24) — 동작은 동일(패널 닫고 본 채팅에서 계속, data-kx-close 재사용)
    // [Continue] instead of ✕ (per design) — same behavior (close the panel, continue in the main chat)
    + '<button type="button" class="ai365-kx-cont" data-kx-close>'
    + '<svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 7 7 17"/><path d="M15 17H7V9"/></svg>'
    + ai365T('이어가기') + '</button></div>'
    + '<div class="ai365-kx-top">'
    + '<div class="ai365-kx-docs"><div class="ai365-kx-docs-hd" data-kx-docsfold><span>' + ai365T(A.docsLabel) + '</span><span class="ai365-flprev-badge">' + docs.length + '</span>'
    + '<span class="ai365-flprev-caret ai365-kpl-caret" style="transform:rotate(180deg)">' + AI365_FLP_PREV_CARET + '</span></div>'
    + '<div class="ai365-kx-docs-list">' + ai365KxDocRows(st) + '</div></div>'
    + '<div class="ai365-kx-view" id="ai365KxView" style="height:' + st.vh + 'px">' + ai365KxExploreContent(st) + '</div>'
    + '<div class="ai365-kx-handle" data-kx-handle><svg width="18" height="8" viewBox="0 0 24 10" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M4 3h16M4 7h16"/></svg></div>'
    + '</div>'
    + '<div class="ai365-kx-thread" id="ai365KxThread">' + st.qa.map(function (x) { return ai365KxQaHtml(x); }).join('') + '</div>'
    + '<div class="ai365-kx-in"><input type="text" id="ai365KxIn" placeholder="' + ai365T('선택한 리소스에 질문하세요') + '">'
    + '<button type="button" class="ai365-kx-send" data-kx-send aria-label="' + ai365T('전송') + '">' + SEND_ICON + '</button></div>';
  artifactPanel.classList.add('open');
  if (typeof updateScrollBtn === 'function') updateScrollBtn();
  if (agent === 'data') ai365DxEnsure('exp');
  const th = document.getElementById('ai365KxThread');
  if (th) th.scrollTop = th.scrollHeight;
}

/* 패널 본문 — 지식=PDF iframe, 데이터=테이블이면 탐색기(Select Source=참조 테이블 전부)·BI면 BI 카드 */
/* Panel content — knowledge = PDF iframe; data = explorer for tables (sources = all referenced tables), BI card for BI */
function ai365KxExploreContent(st) {
  // 그룹웨어 탐색(2026-08-24): 참조한 그룹웨어 자료(일정·조직도 등)의 위젯 답변을 그룹웨어 질의로
  // 불러와 미리보기 + 하단 미니 채팅. 위젯 렌더는 답변 텍스트·항목 목록(간이) — 캘린더 그리드는 후속.
  // Groupware explore: fetch the widget answer for the referenced resource + a mini-chat; a simple
  // text/item preview (a full calendar grid is a follow-up).
  if (st.agent === 'groupware') {
    const d = st.docs.find(function (x) { return x.title === st.cur; }) || st.docs[0];
    ai365KxGwLoad(st, d);
    return '<div class="ai365-kx-gwview" id="ai365KxGwView"><div class="think-row"><span class="spinner"></span>' + ai365T('자료를 불러오는 중입니다') + '</div></div>';
  }
  if (st.agent !== 'data') {
    return '<iframe src="' + ai365KxDocUrl(st) + '" title="' + ai365Esc(st.cur) + '"></iframe>';
  }
  const d = st.docs.find(function (x) { return x.title === st.cur; }) || st.docs[0];
  if (d.kind === 'bi') return '<div class="ai365-kx-view-scroll">' + ai365BiEmbHtml(d.title, '/static/bi_thumbs/' + d.file) + '</div>';
  const tables = st.docs.filter(function (x) { return x.kind !== 'bi'; }).map(function (x) { return { table: x.table, label: x.title, kind: x.typeKind }; });
  ai365DxState('exp', tables, d.table);
  AI365_DX.exp.cur = d.table;
  return ai365DxHtml('exp');
}

function ai365KxDocUrl(st) {
  const d = st.docs.find(function (x) { return x.title === st.cur; }) || st.docs[0];
  return '/api/resources/knowledge/file/' + encodeURIComponent(d.title) + (d.page != null ? '#page=' + encodeURIComponent(d.page) : '');
}

const AI365_KX_GW_IC = '<span class="ai365-flp-file-ic"><svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1.4"/><rect x="14" y="3" width="7" height="7" rx="1.4"/><rect x="3" y="14" width="7" height="7" rx="1.4"/><rect x="14" y="14" width="7" height="7" rx="1.4"/></svg></span>';
function ai365KxDocRows(st) {
  return st.docs.map(function (d) {
    const ic = st.agent === 'groupware' ? AI365_KX_GW_IC
      : (st.agent === 'data' ? ai365KxTypeBadge(d.kind === 'bi' ? 'BI' : d.typeKind) : AI365_KPT_FILE_IC);
    const nm = st.agent === 'data' && d.typeKind === 'CSV' && d.kind !== 'bi' ? d.title + '.csv' : d.title;
    return '<button type="button" class="ai365-kx-doc' + (d.title === st.cur ? ' on' : '') + '" data-kx-doc="' + ai365Esc(d.title) + '">'
      + ic + '<span>' + ai365Esc(nm) + '</span></button>';
  }).join('');
}

/* 그룹웨어 조회 결과(items)를 도구별 필드로 렌더 — 서버 flows._cap_item_lines와 동형(제목·부제) */
/* Render groupware info items per-tool (mirrors server flows._cap_item_lines) */
function ai365KxGwItemsHtml(ns, items) {
  if (!items || !items.length) return '';
  const rows = items.slice(0, 12).map(function (r) {
    let t = '', s = '';
    if (ns === 'mail') { t = r.subject || ''; s = ((r.from || {}).name || '') + (r.when ? ' · ' + r.when : '') + (r.isRead === false ? ' · 안 읽음' : ''); }
    else if (ns === 'calendar') { t = r.subject || ''; s = (r.when || r.timeRange || '') + (r.location ? ' · ' + r.location : ''); }
    else if (ns === 'todo') { t = r.title || ''; s = '마감 ' + (r.due || '') + (r.isOverdue ? ' · 기한 지남' : ''); }
    else { t = r.name || r.title || ''; s = (r.path || '') + (r.when ? ' · ' + r.when : ''); }
    return '<div class="ai365-gw-row"><b>' + ai365Esc(t) + '</b>' + (s ? '<span>' + ai365Esc(s) + '</span>' : '') + '</div>';
  }).join('');
  return '<div class="ai365-gw-list">' + rows + '</div>';
}

/* 그룹웨어 탐색 콘텐츠 로드 — 능력 키(<ns>.info.*)=스마트 실행 /info 직접 조회, 위젯 키=그룹웨어 질의.
   (2026-08-24 수정: 종전 위젯 질의만 써서 calendar.info.*·todo.info.* 등 능력 키가 안 불러와졌다) */
/* Load groupware explore content — capability keys (<ns>.info.*) via smart-actions /info direct read,
   widget keys via groupware query (fix: the widget-only path failed for calendar/todo capability keys) */
function ai365KxGwLoad(st, d) {
  setTimeout(function () {
    const view = document.getElementById('ai365KxGwView');
    if (!view) return;
    const fresh = function () { return document.getElementById('ai365KxGwView') === view && AI365_KX_EXPLORE && AI365_KX_EXPLORE.cur === d.title; };
    const fail = function () { if (document.getElementById('ai365KxGwView') === view) view.innerHTML = '<div class="ai365-fl-none">' + ai365T('불러올 자료가 없습니다') + '</div>'; };
    const isCap = d.key && d.key.indexOf('.info.') >= 0 && d.ns && d.ns !== 'widget';
    // 보안 에이전트 항목(2026-09-07): 대시보드 근거 텍스트 미리보기 + 보안 에이전트 화면 바로가기 버튼(패널 닫고 인앱 뷰 열기)
    // Security agent item (2026-09-07): dashboard grounding preview + a shortcut button to the security screen (closes the panel, opens the in-app view)
    if (d.ns === 'security') {
      const target = String(d.key || '').replace(/^security:/, '');
      ai365Fetch('/api/security/describe?target=' + encodeURIComponent(target))
        .then(function (r) {
          if (!fresh()) return;
          const lines = String((r && r.text) || '').split('\n').filter(function (l) { return l.trim(); });
          view.innerHTML = '<div class="ai365-kx-gwbody">'
            + '<div class="ai365-gw-list">' + lines.map(function (l) { return '<div class="ai365-gw-row"><span>' + ai365Esc(l) + '</span></div>'; }).join('') + '</div>'
            + '<div style="margin-top:12px"><button type="button" class="hd-link ai365-sec-open" data-sec-open style="border:1px solid var(--border);border-radius:9px;padding:7px 12px;font-size:14px;font-weight:700;color:var(--primary);background:#fff;cursor:pointer">' + ai365T('보안 에이전트 화면 열기') + ' ›</button></div>'
            + '</div>';
          const btn = view.querySelector('[data-sec-open]');
          if (btn) btn.addEventListener('click', function () {
            if (typeof closeArtifact === 'function') { try { closeArtifact(); } catch (e) { /* noop */ } }
            if (typeof window.AI365_openSecHome === 'function') window.AI365_openSecHome();
          });
        }).catch(fail);
      return;
    }
    if (isCap) {
      ai365Fetch('/api/smart-actions/info', { method: 'POST', headers: AI365_JSON_HEADERS,
        body: JSON.stringify({ ns: d.ns, key: d.key, acting_user_id: ai365ActingId() }) })
        .then(function (r) {
          if (!fresh()) return;
          if (!r || r.kind !== 'info') { fail(); return; }
          view.innerHTML = '<div class="ai365-kx-gwbody">'
            + (r.summary ? '<div class="ai365-gw-sum">' + ai365Esc(r.summary) + '</div>' : '')
            + ai365KxGwItemsHtml(d.ns, r.items) + '</div>';
        }).catch(fail);
    } else {
      ai365Fetch('/api/groupware/query', { method: 'POST', headers: AI365_JSON_HEADERS,
        body: JSON.stringify({ text: d.title, acting_user_id: ai365ActingId() }) })
        .then(function (r) {
          if (!fresh()) return;
          if (!r || r.kind !== 'answer') { fail(); return; }
          const items = (r.items || []).map(function (it) {
            return '<div class="ai365-gw-row"><b>' + ai365Esc(it.t || '') + '</b>' + (it.s ? '<span>' + ai365Esc(it.s) + '</span>' : '') + '</div>';
          }).join('');
          view.innerHTML = '<div class="ai365-kx-gwbody">' + ai365MnMd(r.text || '') + (items ? '<div class="ai365-gw-list">' + items + '</div>' : '') + '</div>';
        }).catch(fail);
    }
  }, 0);
}

/* 그룹웨어 탐색 미니 채팅 — 현재 자료의 도구(ns)로 라우팅: 능력 ns=/info(분류), 위젯=그룹웨어 질의.
   세션 한정(서버 미영속) — knowledge/data 탐색 행과 달리 복원되지 않는다. */
/* Groupware explore mini-chat — routed by the current resource's tool (ns): capability ns → /info
   (classified), widget → groupware query. Session-only (not persisted / not restored). */
function ai365KxGwExploreSend(st, text, th) {
  const cur = st.docs.find(function (x) { return x.title === st.cur; }) || st.docs[0] || {};
  const wrap = document.createElement('div');
  wrap.className = 'msg msg-ai appear';
  wrap.innerHTML = '<div class="think-row"><span class="spinner"></span>' + ai365T('조회 중입니다') + '</div>';
  th.appendChild(wrap); th.scrollTop = th.scrollHeight;
  const keep = function (ansHtml, ansText) {
    wrap.innerHTML = '<div class="ai-body">' + ansHtml + '</div>';
    const pair = { q: text, a: ansText };
    ai365KxHistPush(st.chatId, st.anchor, st.agent, pair);
    if (AI365_KX_EXPLORE === st) { st.qa.push(pair); st.dirty = true; }
    th.scrollTop = th.scrollHeight;
  };
  const isCap = cur.ns && cur.ns !== 'widget';
  if (isCap) {
    ai365Fetch('/api/smart-actions/info', { method: 'POST', headers: AI365_JSON_HEADERS,
      body: JSON.stringify({ ns: cur.ns, text: text, acting_user_id: ai365ActingId() }) })
      .then(function (r) {
        if (r && r.kind === 'info') keep((r.summary ? '<p>' + ai365Esc(r.summary) + '</p>' : '') + ai365KxGwItemsHtml(cur.ns, r.items), r.summary || '');
        else keep('<p>' + ai365T('해당하는 그룹웨어 자료를 찾지 못했습니다.') + '</p>', ai365T('해당하는 그룹웨어 자료를 찾지 못했습니다.'));
      }).catch(function () { keep('<p>' + ai365T('조회에 실패했습니다.') + '</p>', ''); });
  } else {
    ai365Fetch('/api/groupware/query', { method: 'POST', headers: AI365_JSON_HEADERS,
      body: JSON.stringify({ text: text, acting_user_id: ai365ActingId() }) })
      .then(function (r) {
        const ans = (r && r.kind === 'answer') ? (r.text || '') : ai365T('해당하는 그룹웨어 자료를 찾지 못했습니다.');
        const items = (r && r.items || []).map(function (it) {
          return '<div class="ai365-gw-row"><b>' + ai365Esc(it.t || '') + '</b>' + (it.s ? '<span>' + ai365Esc(it.s) + '</span>' : '') + '</div>';
        }).join('');
        keep(ai365MnMd(ans) + (items ? '<div class="ai365-gw-list">' + items + '</div>' : ''), ans);
      }).catch(function () { keep('<p>' + ai365T('조회에 실패했습니다.') + '</p>', ''); });
  }
}

function ai365KxQaHtml(x) {
  return '<div class="msg msg-user"><div class="user-bubble">' + ai365Esc(x.q) + '</div></div>'
    + '<div class="msg msg-ai"><div class="ai-body">' + ai365MnMd(String(x.a || '')) + '</div></div>';
}

function ai365KxExploreScope(st) {
  if (st.agent === 'data') {
    return { knowledge_files: [],
      data_tables: st.docs.filter(function (d) { return d.kind !== 'bi' && d.table; }).map(function (d) { return d.table; }),
      data_bi: st.docs.filter(function (d) { return d.kind === 'bi' && d.file; }).map(function (d) { return d.file; }),
      work: false };
  }
  return { knowledge_files: st.docs.map(function (d) { return d.title; }), data_tables: [], data_bi: [], work: false };
}

function ai365KxExploreSend() {
  const st = AI365_KX_EXPLORE;
  const inp = document.getElementById('ai365KxIn');
  if (!st || !inp) return;
  const text = (inp.value || '').trim();
  if (!text) return;
  if (typeof replyActive !== 'undefined' && replyActive) { if (typeof toast === 'function') toast(ai365T('답변이 끝난 뒤 질문해 주세요.')); return; }
  if (!currentChatId || currentChatId !== st.chatId || !AI365_BACKEND_IDS.has(currentChatId)) {
    if (typeof toast === 'function') toast(ai365T('이 채팅에서만 탐색할 수 있습니다.'));
    return;
  }
  inp.value = '';
  const th = document.getElementById('ai365KxThread');
  if (!th) return;
  th.insertAdjacentHTML('beforeend', '<div class="msg msg-user"><div class="user-bubble">' + ai365Esc(text) + '</div></div>');
  // 그룹웨어 탐색은 그룹웨어 질의 경로로(knowledge/data의 /stream 에이전트 경로와 다름)
  // Groupware explore uses the groupware query path (not the knowledge/data /stream agent path)
  if (st.agent === 'groupware') { ai365KxGwExploreSend(st, text, th); return; }
  const wrap = document.createElement('div');
  wrap.className = 'msg msg-ai appear';
  th.appendChild(wrap);
  th.scrollTop = th.scrollHeight;
  const mo = new MutationObserver(function () { th.scrollTop = th.scrollHeight; });
  mo.observe(wrap, { childList: true, subtree: true, characterData: true });
  ai365StreamReply(text, {
    wrap: wrap, agents: [st.agent], scope: '사내', explore: true, exploreAnchor: st.anchor, noKx: true,
    scopeFiles: ai365KxExploreScope(st),
    onEnd: function (state) {
      mo.disconnect();
      // done까지 간 문답만 적재 — 중단(STOP·패널 닫힘)·오류의 부분 답변은 서버에도 explore 답변 행이 남지
      // 않으므로(라이브/복원 어긋남) 히스토리·세션 qa 모두 건너뛴다(리뷰 확정).
      // Only pairs that reached 'done' are kept — aborted/errored partial answers leave no explore answer
      // row on the server either, so both the history and the session qa skip them (review finding).
      if (state.done) {
        const pair = { q: text, a: state.text || '' };
        ai365KxHistPush(st.chatId, st.anchor, st.agent, pair);   // 패널이 닫혀도 이 탐색의 히스토리에는 남는다 / kept per exploration
        if (AI365_KX_EXPLORE === st) { st.qa.push(pair); st.dirty = true; }
      }
      th.scrollTop = th.scrollHeight;
    },
  });
}

document.addEventListener('click', function (e) {
  const ex = e.target.closest('[data-kx-explore]');
  if (ex) {
    if (ex.disabled) return;
    const sid = ex.getAttribute('data-kx-explore');
    const msg = ex.closest('.msg');
    const th = msg && msg.querySelector('.ai365-agx-think');
    if (th) th.classList.add('fold');   // 시안 5: 탐색 중엔 트리 접힘 / design 5: the tree folds while exploring
    // 탐색 가능한 에이전트(knowledge/data/groupware) — 카드가 넘긴 값을 그대로 쓰되 미지값은 knowledge로
    // Explore-capable agents (knowledge/data/groupware) — use the card's value, unknown falls back to knowledge
    let agent = ex.getAttribute('data-kx-agent') || 'knowledge';
    if (!(AI365_KX_AGENT[agent] && AI365_KX_AGENT[agent].explore)) agent = 'knowledge';
    const reg = AI365_KX_DOCS[sid] || {};
    const src = AI365_SRC_REG[sid] || {};
    const items = reg[agent] || ((src[agent] && src[agent].items) || []);
    const mid = reg.mid || sid;   // 앵커 미확정(이론상 done 전)이면 세션 한정 sid 키 / sid fallback = session-local only
    ai365KxExploreOpen(agent, ai365KxDocList(agent, items), ai365KxHistList(currentChatId, mid, agent), currentChatId, mid);
    return;
  }
  if (e.target.closest('[data-kx-close]')) { closeArtifact(); return; }
  if (e.target.closest('[data-kx-send]')) { ai365KxExploreSend(); return; }
  const fold = e.target.closest('[data-kx-docsfold]');
  if (fold) {
    const list = fold.parentElement.querySelector('.ai365-kx-docs-list');
    const car = fold.querySelector('.ai365-kpl-caret');
    if (list) { const hid = list.style.display === 'none'; list.style.display = hid ? '' : 'none'; if (car) car.style.transform = hid ? 'rotate(180deg)' : ''; }
    return;
  }
  const doc = e.target.closest('[data-kx-doc]');
  if (doc && AI365_KX_EXPLORE) {
    const st = AI365_KX_EXPLORE;
    st.cur = doc.getAttribute('data-kx-doc');
    const list = doc.parentElement;
    if (list) list.innerHTML = ai365KxDocRows(st);
    const view = document.getElementById('ai365KxView');
    if (view) { view.innerHTML = ai365KxExploreContent(st); if (st.agent === 'data') ai365DxEnsure('exp'); }
  }
});
document.addEventListener('keydown', function (e) {
  if (e.key === 'Enter' && !e.isComposing && e.target && e.target.id === 'ai365KxIn') { e.preventDefault(); ai365KxExploreSend(); }
});
// 뷰어/대화 경계 드래그(시안 5의 ≡ 손잡이) / drag the viewer/thread boundary (the ≡ handle in design 5)
document.addEventListener('mousedown', function (e) {
  const h = e.target.closest('[data-kx-handle]');
  if (!h) return;
  const view = document.getElementById('ai365KxView');
  if (!view) return;
  e.preventDefault();
  const y0 = e.clientY, h0 = view.offsetHeight;
  const move = function (ev) {
    const nh = Math.max(120, Math.min(Math.round(window.innerHeight * 0.7), h0 + (ev.clientY - y0)));
    view.style.height = nh + 'px';
    if (AI365_KX_EXPLORE) AI365_KX_EXPLORE.vh = nh;
  };
  const up = function () { document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); };
  document.addEventListener('mousemove', move);
  document.addEventListener('mouseup', up);
});

/* 탐색 종료 알림 — 우상단 알림 카드(2026-08-24 시안 교체: 녹색 체크 배지 + 안내 문구 + ✕ 닫기).
   종전 하단 연보라 바 토스트를 대체하며, 에이전트 구분 없는 공통 문구를 쓴다(시안 그대로). */
/* Explore-finished notice — top-right notification card (design swap: green check badge + copy +
   ✕ close). Replaces the old bottom soft-indigo bar; one shared message for every agent (per design). */
function ai365KxToast(agent) {
  let el = document.getElementById('ai365KxToast');
  if (!el) { el = document.createElement('div'); el.id = 'ai365KxToast'; document.body.appendChild(el); }
  el.innerHTML = '<span class="ic"><svg width="16" height="16" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#2E7D32"/><path d="m7.6 12.4 2.9 2.9 5.9-6.4" stroke="#fff" stroke-width="2.2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></span>'
    + '<span class="tx">' + ai365T('리소스 탐색을 마쳤습니다. 이제 전체 채팅에서 자유롭게 질문해 보세요.') + '</span>'
    + '<button type="button" class="x" aria-label="' + ai365T('닫기') + '"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><path d="M6 6l12 12M18 6 6 18"/></svg></button>';
  el.querySelector('.x').addEventListener('click', function () { clearTimeout(el._t); el.classList.remove('show'); });
  el.classList.remove('show');
  void el.offsetWidth;   // 연속 발화 시 페이드 재시작 / restart the fade on back-to-back toasts
  el.classList.add('show');
  clearTimeout(el._t);
  el._t = setTimeout(function () { el.classList.remove('show'); }, 5200);
}

/* 닫힘 정리 — 어떤 경로(✕·채팅 전환·다른 아티팩트)로 닫혀도 탐색 모드 클래스와 상태를 비운다 */
/* Close hygiene — whatever closes the panel (✕, chat switch, another artifact) clears explore mode & state */
(function () {
  function kxClear() {
    ai365KxAbortPanelStream();
    const st = AI365_KX_EXPLORE;
    artifactPanel.classList.remove('ai365-explore');
    AI365_KX_EXPLORE = null;
    // 새 문답이 생긴 세션을 닫으면 토스트만 — 본 채팅에 카드를 남기지 않는다(2026-08-24 사용자 지시)
    // Closing a session that produced new Q&A shows just a toast — no card in the main chat (user request)
    if (st && st.dirty) ai365KxToast(st.agent);
  }
  const prevClose = closeArtifact;
  closeArtifact = function () { kxClear(); return prevClose.apply(this, arguments); };
  const prevOpenArt = openArtifact;
  openArtifact = function (type, opts) { kxClear(); return prevOpenArt(type, opts); };
  // 리소스 목록·지식 미리보기·리포트 패널은 탐색 모드를 대체한다 — 같은 정리(리뷰 확정: 모드 클래스 누수)
  // Resource list / knowledge preview / report panels replace explore mode — same cleanup (review finding: class leak)
  ['ai365OpenSources', 'ai365OpenKnowledgePreview', 'ai365OpenReport'].forEach(function (name) {
    const prev = window[name];
    if (typeof prev !== 'function') return;
    window[name] = function () { kxClear(); return prev.apply(this, arguments); };
  });
  if (window.MutationObserver) {
    new MutationObserver(function () {
      if (!artifactPanel.classList.contains('open') && artifactPanel.classList.contains('ai365-explore')) kxClear();
    }).observe(artifactPanel, { attributes: true, attributeFilter: ['class'] });
  }
})();

