/* 위험 확인 창(2026-10-28 Dev 원본 정렬): 게시판 · 예약 작업의 삭제는 window.confirm 대신 이 창을 쓴다. 마크업 · 클래스가 목업
   #deleteOverlay(채팅 삭제)와 같아(.overlay > .dialog > .dialog-head · .dialog-body · .dialog-actions) ai365DevAlign 의 위험 확인 규칙
   (480 · 그림자 64 · 본문 14 #21242C · 버튼 16/22 · 빨강 #CC2635 오른쪽, 데모 [취소][삭제] 유지)을 같이 쓴다. 약속 = [삭제] true, 그 밖(취소 ·
   닫기 · 바깥 · Esc) false. 열려 있는데 또 부르면 앞 창은 false 로 닫힌다. 문구(o.title · o.body · o.ok)는 한국어로 넘기면 ai365T 로 번역한다.
   Danger confirm (Dev-original alignment, 2026-10-28): board and schedule deletes use this instead of window.confirm. Its markup and
   classes match the mockup's #deleteOverlay (chat delete), so the danger-confirm rules in ai365DevAlign (480, shadow 64, 14px #21242C
   body, 16/22 buttons, red #CC2635 on the right, the demo's [Cancel][Delete] kept) cover it. The promise is true on [Delete] and false on
   anything else (cancel, close, backdrop, Esc); a second call closes the first with false. Korean o.title, o.body and o.ok go through ai365T. */
function ai365DangerConfirm(opts) {
  const o = opts || {};
  const T = (typeof ai365T === 'function') ? ai365T : function (s) { return s; };
  const E = (typeof ai365Esc === 'function') ? ai365Esc : function (s) { return String(s == null ? '' : s); };
  if (typeof ai365DangerConfirm.close === 'function') ai365DangerConfirm.close(false);
  return new Promise(function (resolve) {
    let ov = document.getElementById('ai365DcOv');
    if (!ov) { ov = document.createElement('div'); ov.className = 'overlay'; ov.id = 'ai365DcOv'; document.body.appendChild(ov); }
    const X = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><line x1="5" y1="5" x2="19" y2="19"/><line x1="19" y1="5" x2="5" y2="19"/></svg>';
    ov.innerHTML = '<div class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="ai365DcT" aria-describedby="ai365DcB">'
      + '<div class="dialog-head"><span class="dialog-title" id="ai365DcT">' + E(T(o.title || '삭제')) + '</span>'
      + '<button type="button" class="icon-btn" data-dc="0" aria-label="' + E(T('닫기')) + '">' + X + '</button></div>'
      + '<div class="dialog-body" id="ai365DcB">' + E(T(o.body || '')) + '</div>'
      + '<div class="dialog-actions"><button type="button" class="btn btn-ghost" data-dc="0">' + E(T('취소')) + '</button>'
      + '<button type="button" class="btn btn-danger" data-dc="1">' + E(T(o.ok || '삭제')) + '</button></div></div>';
    const prev = document.activeElement;
    const close = function (v) {
      if (ai365DangerConfirm.close !== close) return;
      ai365DangerConfirm.close = null;
      ov.classList.remove('show');
      ov.removeEventListener('click', onClick);
      document.removeEventListener('keydown', onKey, true);
      try { if (prev && prev.focus && document.contains(prev)) prev.focus(); } catch (e) { /* noop */ }
      resolve(!!v);
    };
    const onClick = function (e) {
      if (e.target === ov) { close(false); return; }
      const b = e.target.closest && e.target.closest('[data-dc]');
      if (b) close(b.getAttribute('data-dc') === '1');
    };
    const onKey = function (e) { if (e.key === 'Escape') { e.preventDefault(); e.stopPropagation(); close(false); } };
    ai365DangerConfirm.close = close;
    ov.addEventListener('click', onClick);
    document.addEventListener('keydown', onKey, true);
    ov.classList.add('show');
    const c = ov.querySelector('.btn-ghost');
    if (c) c.focus();   // 위험 동작이라 처음 포커스는 [취소] / the first focus is [Cancel] for a destructive action
  });
}

